INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A large enterprise uses AWS Organizations and requires a centralized security posture management solution. They need to aggregate security findings from various AWS services, monitor compliance against industry standards like CIS Benchmarks, and automate responses to critical findings with LEAST operational overhead.', '["Enable Amazon Security Hub in the management account and delegate it to a member account, then enable GuardDuty, Amazon Macie, and AWS Config across all accounts and integrate their findings into Security Hub.","Enable Amazon GuardDuty in each account, configure Amazon EventBridge rules to send GuardDuty findings to a central Amazon S3 bucket, and use Amazon Athena for analysis.","Deploy AWS Config rules in each account to monitor for compliance, use AWS CloudTrail to log all API activity, and manually review logs for security incidents.","Implement a custom solution using AWS Lambda functions to collect findings from various services, store them in Amazon DynamoDB, and build a custom dashboard with Amazon QuickSight."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended and most efficient approach for centralized security posture management in an AWS Organizations setup. Amazon Security Hub aggregates, normalizes, and prioritizes findings from various AWS services (like GuardDuty, Macie, Config) and third-party products. It also provides compliance checks against standards like CIS Benchmarks. Delegating Security Hub to a member account allows for centralized management and monitoring across the organization with minimal operational overhead. Option B (incorrect) is an anti-pattern (ap-1.2-001). While GuardDuty is crucial, relying solely on GuardDuty findings sent to S3 and analyzed by Athena misses the comprehensive aggregation, normalization, and compliance monitoring capabilities of Security Hub. It also requires more custom development for analysis and reporting. Option C (incorrect) focuses only on configuration compliance and logging, missing threat detection (GuardDuty, Macie) and centralized aggregation. Manually reviewing CloudTrail logs for security incidents is highly inefficient and prone to human error, leading to significant operational overhead. Option D (incorrect) involves building a custom solution, which would incur significant development, maintenance, and operational overhead. AWS Security Hub provides these capabilities natively, making a custom solution unnecessary and less efficient for this requirement.', 54, 'm_54_2', 6, NULL, NULL),
  ('mock_54_all_1775000123948', 'A financial services company needs to detect unusual API activity that could indicate a compromised credential or insider threat. They require a service that automatically identifies anomalous patterns in AWS API calls without requiring extensive manual configuration or baseline establishment.', '["Enable AWS CloudTrail Insights in all accounts, which automatically detects and alerts on unusual API activity patterns.","Configure Amazon GuardDuty to monitor AWS CloudTrail logs for suspicious API calls and integrate findings with Amazon Security Hub.","Set up Amazon CloudWatch Alarms to monitor specific API call counts in AWS CloudTrail logs and alert when thresholds are exceeded.","Use Amazon Athena to query AWS CloudTrail logs periodically for specific API calls from unusual IP addresses or user agents."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable service for detecting unusual API activity without extensive manual configuration. AWS CloudTrail Insights automatically analyzes CloudTrail events for unusual activity, such as a spike in resource provisioning or API calls from an unusual location, and generates findings. It uses machine learning to establish baselines and detect anomalies. Option B (incorrect) is a good practice for general threat detection, but Amazon GuardDuty''s focus is broader than just ''unusual API activity patterns'' as defined by CloudTrail Insights. While GuardDuty does analyze CloudTrail events for various threats, CloudTrail Insights is specifically designed for behavioral anomaly detection in API usage. Option C (incorrect) would require significant manual effort to identify ''specific API call counts'' and define appropriate thresholds for all potential anomalous behaviors. This approach is not automatic and would generate many false positives or miss subtle anomalies. Option D (incorrect) is a reactive and manual approach. Periodically querying logs with Amazon Athena is useful for deep forensic analysis but does not provide real-time, automatic detection of unusual API activity without extensive custom scripting and continuous monitoring.', 54, 'm_54_2', 7, NULL, NULL),
  ('mock_54_all_1775000123948', 'A healthcare organization stores sensitive patient data in Amazon S3 buckets. They need to automatically discover, classify, and report on personally identifiable information (PII) and protected health information (PHI) within these buckets to ensure compliance with data privacy regulations, while minimizing manual effort.', '["Enable Amazon Macie to automatically discover and classify sensitive data, including PII and PHI, in Amazon S3 buckets.","Configure AWS Config rules to monitor S3 bucket policies for public access and report on any non-compliant configurations.","Use Amazon GuardDuty to detect unusual access patterns to S3 buckets that might indicate data exfiltration.","Implement a custom solution using AWS Lambda functions to scan S3 objects for sensitive data based on predefined regex patterns."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for this purpose. Amazon Macie is a data security and data privacy service that uses machine learning and pattern matching to discover, classify, and report on sensitive data, including PII and PHI, stored in Amazon S3. It provides automated and continuous monitoring with minimal manual effort. Option B (incorrect) focuses on S3 bucket policy compliance (public access) rather than the content of the objects within the buckets. While important for security, it does not address the requirement to discover and classify sensitive data like PII/PHI. Option C (incorrect) is for threat detection related to S3 access patterns, not for discovering and classifying sensitive data within the objects themselves. GuardDuty would alert on suspicious activity, but not identify the type of data being accessed. Option D (incorrect) would involve significant development and maintenance overhead. While technically possible, building a custom Lambda-based solution for sensitive data discovery and classification is complex, prone to errors, and would require continuous updates for new data types or patterns, making it less efficient than a managed service like Amazon Macie.', 54, 'm_54_2', 8, NULL, NULL),
  ('mock_54_all_1775000123948', 'A global company needs to establish a robust threat detection system across its multi-account AWS environment. They want to identify potential threats like cryptocurrency mining, unauthorized access, and compromised instances, and centralize these findings for security analysts, with MINIMAL configuration effort.', '["Enable Amazon GuardDuty in all accounts and configure it to send findings to a delegated administrator account, which then aggregates them in Amazon Security Hub.","Enable AWS CloudTrail in all accounts and configure Amazon CloudWatch Logs to centralize all logs, then use Amazon Athena to query for suspicious activities.","Deploy AWS Config rules in each account to monitor for suspicious resource changes and use Amazon SNS to notify a central security team.","Implement a custom solution using AWS Lambda functions to parse VPC Flow Logs, CloudTrail logs, and DNS logs for anomalies and store them in Amazon OpenSearch Service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and operationally efficient solution. Amazon GuardDuty is a managed threat detection service that continuously monitors for malicious activity and unauthorized behavior (including cryptocurrency mining, compromised instances, and unusual API calls). By enabling GuardDuty in all accounts and integrating its findings with Amazon Security Hub in a delegated administrator account, the company achieves centralized threat detection and aggregation with minimal configuration effort. Option B (incorrect) requires significant manual effort to define queries and analyze logs for specific threats. While CloudTrail and CloudWatch Logs are essential for auditing, they don''t provide automated threat detection like GuardDuty. Option C (incorrect) focuses on configuration changes rather than active threats like cryptocurrency mining or unauthorized access. AWS Config is for compliance and configuration drift, not real-time threat detection. Option D (incorrect) involves building a complex custom solution, which would incur significant development, maintenance, and operational overhead. GuardDuty and Security Hub provide these capabilities natively and are designed for scale and minimal configuration.', 54, 'm_54_2', 9, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company needs to continuously monitor its AWS environment for unauthorized configuration changes to critical resources like security groups and S3 bucket policies. They require a service that can automatically detect these changes and report on compliance against predefined rules.', '["AWS Config to continuously monitor resource configurations, detect non-compliant changes, and evaluate against predefined rules.","Amazon GuardDuty to detect suspicious API calls that indicate unauthorized configuration changes to resources.","AWS CloudTrail to log all API calls, then use Amazon CloudWatch Alarms to alert on specific API calls related to configuration changes.","Amazon Security Hub to aggregate findings from various services and manually review them for unauthorized configuration changes."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the primary service for this requirement. AWS Config continuously monitors and records your AWS resource configurations and allows you to automate the evaluation of recorded configurations against desired configurations. It can detect unauthorized changes to security groups, S3 bucket policies, and other critical resources and report on compliance. Option B (incorrect) is a threat detection service. While Amazon GuardDuty might detect some suspicious API calls related to configuration changes if they are part of a broader threat, its primary purpose is not continuous configuration compliance monitoring. Option C (incorrect) is a reactive approach that requires significant manual effort to define specific API calls and thresholds for every potential unauthorized change. While CloudTrail logs all API calls, CloudWatch Alarms are not designed for comprehensive configuration compliance evaluation. Option D (incorrect) is for aggregating findings from multiple services, not for actively detecting unauthorized configuration changes itself. While Amazon Security Hub would display AWS Config findings, it doesn''t perform the continuous monitoring and evaluation that AWS Config does.', 54, 'm_54_2', 10, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security team needs to analyze network traffic patterns within their VPCs to detect potential anomalies, such as unusual port scans or large data transfers to suspicious external IPs. They want to capture detailed information about IP traffic for forensic analysis and threat detection.', '["Enable VPC Flow Logs to capture detailed information about IP traffic, then send the logs to Amazon CloudWatch Logs or Amazon S3 for analysis.","Use Amazon GuardDuty to monitor VPC network activity for known threats and suspicious behavior.","Deploy a third-party Network Intrusion Detection System (NIDS) on an EC2 instance within the VPC to inspect traffic.","Configure AWS Config rules to monitor network ACLs and security groups for unauthorized changes that could indicate a threat."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirement. VPC Flow Logs capture detailed information about the IP traffic going to and from network interfaces in your VPC. This includes source/destination IP, port, protocol, and action (ACCEPT/REJECT). Sending these logs to Amazon CloudWatch Logs or Amazon S3 allows for analysis to detect anomalies like unusual port scans or large data transfers. Option B (incorrect) is a threat detection service that uses various data sources, including VPC Flow Logs, but it provides high-level findings rather than the raw, detailed traffic information needed for deep forensic analysis of specific patterns. While GuardDuty is excellent for threat detection, VPC Flow Logs provide the raw data for custom anomaly detection. Option C (incorrect) introduces significant operational overhead and cost. Deploying and managing a third-party NIDS requires EC2 instances, licensing, and expertise, which is more complex than using a native AWS logging service for traffic analysis. Option D (incorrect) focuses on configuration compliance of network controls, not on analyzing the actual network traffic patterns. While important for security, it does not provide the visibility into IP traffic needed for anomaly detection.', 54, 'm_54_2', 11, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company needs to centralize security findings from Amazon GuardDuty, Amazon Macie, and AWS Config across multiple AWS accounts into a single pane of glass. They also want to continuously monitor their environment against AWS security best practices and industry standards like PCI DSS. Which service is BEST suited for this requirement?', '["Amazon Security Hub, configured as a delegated administrator in AWS Organizations, to aggregate findings and monitor compliance.","Amazon CloudWatch, with custom dashboards and alarms, to collect logs and metrics from all security services.","AWS CloudTrail, configured to log all API activity to a central Amazon S3 bucket, and Amazon Athena for querying.","AWS Systems Manager, using Explorer and OpsCenter, to gather operational data and manage security incidents."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is precisely what Amazon Security Hub is designed for. It provides a comprehensive view of your security posture across your AWS accounts by aggregating, organizing, and prioritizing security findings from various AWS services (like GuardDuty, Macie, Config, Inspector) and third-party solutions. It also includes automated checks against AWS security best practices and industry standards like PCI DSS. Configuring it as a delegated administrator in AWS Organizations allows for centralized management across multiple accounts. Option B (incorrect) would require significant manual effort to create custom dashboards and alarms for each security service and finding type. While Amazon CloudWatch is a powerful monitoring tool, it doesn''t offer the built-in aggregation, normalization, and compliance checks that Security Hub provides for security findings. Option C (incorrect) focuses on logging and querying API activity. While AWS CloudTrail and Amazon Athena are essential for auditing and forensic analysis, they do not provide the centralized security posture management, finding normalization, or compliance monitoring capabilities that Security Hub offers. Option D (incorrect) is primarily for operational insights and incident management, not for aggregating security findings from various services or monitoring compliance against security standards. While it can be part of an incident response workflow, it''s not the ''single pane of glass'' for security posture.', 54, 'm_54_2', 12, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security operations center (SOC) needs to centralize and normalize security findings from Amazon GuardDuty, AWS Config, and a third-party vulnerability scanner. They also require the ability to prioritize these findings based on severity and integrate with existing ticketing systems for remediation. Which AWS service should they use?', '["Amazon Security Hub to aggregate, normalize, and prioritize findings from various sources and integrate with other tools.","Amazon EventBridge to route findings from each service to a central AWS Lambda function for custom processing and ticketing.","Amazon CloudWatch Logs to collect all security logs and then use Amazon Athena for querying and generating reports.","AWS Systems Manager Incident Manager to manage the lifecycle of security incidents and automate response playbooks."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the primary service for centralizing, normalizing, and prioritizing security findings. Amazon Security Hub aggregates findings from GuardDuty, Config, Macie, Inspector, and many third-party security products into a single, normalized format (AWS Security Finding Format - ASFF). It allows for prioritization based on severity and offers integrations with ticketing systems (e.g., Jira) and other AWS services for automated remediation. Option B (incorrect) would require significant custom development to normalize, prioritize, and integrate findings from multiple sources. While Amazon EventBridge is excellent for event routing, building a custom Lambda function to replicate Security Hub''s functionality would incur high development and maintenance overhead. Option C (incorrect) focuses on log collection and querying. While Amazon CloudWatch Logs and Amazon Athena are valuable for forensic analysis and reporting, they do not provide the built-in aggregation, normalization, prioritization, or integration capabilities for security findings that Security Hub offers. Option D (incorrect) is for managing the lifecycle of incidents and automating response playbooks once a finding has been identified and triaged. It complements Security Hub but does not perform the initial aggregation, normalization, and prioritization of findings from disparate sources.', 54, 'm_54_2', 13, NULL, NULL);

