INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A large enterprise with multiple AWS accounts in an AWS Organization needs to centralize all security-related logs for long-term retention and analysis, ensuring data integrity and a unified view across the organization. The solution must be highly scalable and cost-effective for petabytes of data, while supporting future advanced analytics. Which approach meets these requirements with the LEAST operational overhead?', '["Configure an organization trail in AWS CloudTrail to deliver logs to a central Amazon S3 bucket, enable S3 Object Lock, and ingest S3 logs into Amazon Security Lake.","Set up individual CloudTrail trails in each account to deliver logs to their respective Amazon S3 buckets, then use AWS Lambda to aggregate logs to a central Amazon OpenSearch Service domain.","Deploy Amazon Kinesis Data Firehose in each account to stream CloudTrail logs to a central Amazon S3 bucket, then use AWS Glue to transform logs for Amazon OpenSearch Service.","Enable CloudWatch Logs for all services in each account, create metric filters for security events, and stream all CloudWatch Logs to a central Amazon S3 bucket using CloudWatch Logs Subscriptions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages an organization trail in AWS CloudTrail for centralized logging across all accounts, which is a best practice for multi-account environments and cannot be disabled by member accounts. Delivering logs to Amazon S3 provides highly scalable and cost-effective long-term storage. Enabling S3 Object Lock ensures immutability for compliance and data integrity. Ingesting these logs into Amazon Security Lake automatically aggregates security data in OCSF format, centralizing it for analysis with minimal operational overhead and preparing it for future advanced analytics, including integration with OpenSearch Service or Athena. Option B (incorrect) uses per-account CloudTrail trails, which is an anti-pattern (ap-2.1-002) as it requires individual configuration and can be disabled by account administrators. Aggregating with AWS Lambda adds significant operational overhead for managing the Lambda functions and potential scaling issues. Option C (incorrect) introduces Amazon Kinesis Data Firehose, which adds complexity and cost for log ingestion, and AWS Glue for transformation further increases operational overhead compared to Security Lake''s automated aggregation. Option D (incorrect) involves enabling CloudWatch Logs for all services and then streaming them to S3, which can be very costly due to CloudWatch Logs ingestion and storage, especially if all logs are streamed without selective filtering (ap-2.2-001). It also doesn''t inherently provide the OCSF format or centralized aggregation capabilities of Security Lake.', 55, 'm_55_5', 8, NULL, NULL),
  ('mock_54_all_1775000123948', 'A large enterprise needs to centralize and analyze security logs from multiple AWS accounts, including AWS CloudTrail, VPC Flow Logs, and DNS logs. The security team requires a solution that can perform complex queries across these diverse log types, normalize the data into a common format, and integrate with existing security tools for threat detection, with the LEAST effort for data ingestion and schema management.', '["Ingest all logs into Amazon Security Lake, which automatically normalizes data to OCSF, and then query using Amazon Athena.","Stream all logs to Amazon Kinesis Data Firehose, transform them with AWS Lambda, and then store in Amazon S3 for querying with Amazon Athena.","Configure AWS CloudTrail to deliver logs to Amazon CloudWatch Logs, and use CloudWatch Logs Insights for analysis across all accounts.","Deliver all logs to Amazon S3 buckets, use AWS Glue crawlers to infer schemas, and then query the data using Amazon OpenSearch Service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages Amazon Security Lake, which is specifically designed for centralizing security data from various sources, automatically normalizing it to the Open Cyber Security Schema Framework (OCSF) format, and making it available for querying via Amazon Athena. This approach significantly reduces the effort for data ingestion, schema management, and integration with other security tools, aligning with the "LEAST effort" constraint.
Option B (incorrect) involves custom transformations with AWS Lambda, which adds significant operational overhead and development effort for schema management and normalization, failing the "LEAST effort" constraint. While technically possible, it''s not the most efficient for automatic normalization.
Option C (incorrect) limits the scope of analysis primarily to CloudWatch Logs Insights, which is effective for logs already in CloudWatch Logs but does not natively support the ingestion and normalization of diverse log types like VPC Flow Logs or DNS logs from multiple accounts as efficiently as Security Lake. It also doesn''t provide the OCSF normalization.
Option D (incorrect) requires manual setup of AWS Glue crawlers for schema inference and then managing an Amazon OpenSearch Service cluster. This introduces considerable operational overhead for cluster management, scaling, and maintaining the OpenSearch Service environment, which does not meet the "LEAST effort" requirement compared to Security Lake''s managed approach.', 55, 'm_55_5', 9, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company''s security team needs to investigate suspicious API calls detected by AWS GuardDuty across several AWS accounts. They require a solution that allows them to quickly search and analyze AWS CloudTrail management events, identify patterns, and correlate activities over the past 90 days without managing any underlying infrastructure.', '["Consolidate CloudTrail logs into Amazon S3, and then use Amazon Athena to query the logs directly.","Utilize AWS CloudTrail Lake to aggregate and query CloudTrail events directly, leveraging its SQL-like interface for analysis.","Stream CloudTrail logs to Amazon Kinesis Data Firehose, then to Amazon OpenSearch Service, and build dashboards for analysis.","Configure CloudTrail to send logs to Amazon CloudWatch Logs, and then use CloudWatch Logs Insights for advanced querying."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS CloudTrail Lake, which is a purpose-built, serverless data lake for CloudTrail events. It allows security teams to aggregate, immutably store, and query CloudTrail events using a SQL-like interface for up to seven years, without managing any underlying infrastructure. This directly addresses the need for quick search, pattern identification, and correlation over the past 90 days with a managed service.
Option A (incorrect) requires setting up and managing Amazon Athena, including defining tables and schemas over the S3 logs. While effective, it involves more setup and management than CloudTrail Lake, which is specifically designed for CloudTrail events and offers a more integrated experience for this specific use case.
Option C (incorrect) involves multiple services (Amazon Kinesis Data Firehose, Amazon OpenSearch Service) that require significant operational overhead for deployment, configuration, and ongoing management of the OpenSearch Service cluster. This contradicts the requirement of "without managing any underlying infrastructure."
Option D (incorrect) sends logs to Amazon CloudWatch Logs. While CloudWatch Logs Insights is powerful for querying, CloudTrail Lake is optimized specifically for CloudTrail events, offering a more direct and often more cost-effective solution for long-term CloudTrail event analysis, especially when dealing with large volumes and extended retention.', 55, 'm_55_5', 10, NULL, NULL),
  ('mock_54_all_1775000123948', 'A financial institution needs to monitor security events and anomalies in real-time across its AWS environment, including API calls, resource configuration changes, and network activity. They require a solution that can ingest diverse log types, perform real-time analysis, detect known threats, and visualize security posture through dashboards, while minimizing the need for custom development.', '["Send all logs to Amazon S3, then use Amazon Athena for periodic batch analysis and reporting.","Configure Amazon CloudWatch metric filters on CloudTrail logs to trigger Amazon SNS notifications for specific events.","Stream all security logs (CloudTrail, VPC Flow Logs, DNS logs) to Amazon Kinesis Data Firehose, then to Amazon OpenSearch Service, and use OpenSearch Dashboards for real-time visualization and anomaly detection.","Centralize logs in Amazon Security Lake, then use AWS CloudTrail Lake for anomaly detection and reporting."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a robust solution for real-time security monitoring and anomaly detection. Streaming diverse logs via Amazon Kinesis Data Firehose to Amazon OpenSearch Service allows for real-time ingestion, indexing, and analysis. OpenSearch Dashboards can then be used to create interactive dashboards for visualization and to implement anomaly detection features, minimizing custom development for these specific requirements.
Option A (incorrect) focuses on batch analysis with Amazon Athena, which is not suitable for real-time monitoring and anomaly detection. It would introduce significant delays in identifying and responding to security events.
Option B (incorrect) is useful for specific, known events but lacks the comprehensive real-time analysis, correlation, and visualization capabilities required for detecting unknown anomalies across diverse log types. It''s a component of a monitoring solution, not a complete real-time analysis platform.
Option D (incorrect) uses Amazon Security Lake for centralization and AWS CloudTrail Lake for querying. While Security Lake is excellent for data aggregation and normalization, CloudTrail Lake is specifically for CloudTrail events and does not provide real-time anomaly detection or comprehensive dashboarding for all log types in the same way Amazon OpenSearch Service does. Security Lake integrates with other SIEMs, but OpenSearch Service is a direct SIEM solution.', 55, 'm_55_5', 11, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security operations team needs to quickly identify unusual API calls made by IAM users within the last 24 hours across several AWS accounts. The team requires a cost-effective solution for ad-hoc analysis of existing CloudTrail logs that are already delivered to Amazon CloudWatch Logs.', '["Export CloudTrail logs from Amazon CloudWatch Logs to Amazon S3 and then use Amazon Athena for analysis.","Utilize Amazon CloudWatch Logs Insights to run interactive queries on the CloudTrail logs stored in CloudWatch Logs.","Ingest all CloudTrail logs into Amazon OpenSearch Service (SIEM) for detailed analysis and dashboarding.","Configure AWS Security Lake to aggregate and normalize CloudTrail logs for query by external SIEM tools."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) leverages Amazon CloudWatch Logs Insights, which is specifically designed for interactive and powerful querying of log data already stored in Amazon CloudWatch Logs. It provides a cost-effective and fast way to perform ad-hoc analysis without moving data or managing additional infrastructure. Option A (incorrect) would involve unnecessary data transfer and processing costs by exporting logs from CloudWatch Logs to S3 and then querying with Athena, which is less efficient for logs already in CloudWatch Logs. Option C (incorrect) would introduce significant operational overhead and cost for managing an Amazon OpenSearch Service cluster, which is overkill for quick ad-hoc queries on existing logs. Option D (incorrect) is for centralized security data aggregation and normalization, which is beneficial for long-term storage and broader SIEM integration, but not the most cost-effective or direct solution for immediate ad-hoc querying of existing CloudTrail logs in CloudWatch Logs.', 55, 'm_55_5', 12, NULL, NULL);

