INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A large enterprise needs to provide its workforce with single sign-on (SSO) access to multiple AWS accounts. The company already uses an on-premises Microsoft Active Directory for user management and wants to integrate this with AWS. The solution must offer the LEAST operational overhead for identity management.', '["Deploy AWS IAM Identity Center and integrate it with the on-premises Active Directory using AWS Directory Service.","Create individual IAM users in each AWS account and manually synchronize them with the on-premises Active Directory.","Set up an Amazon Cognito User Pool and configure it to federate with the on-premises Active Directory.","Establish a trust relationship between the on-premises Active Directory and each AWS account using SAML 2.0 federation directly with IAM."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended approach for workforce SSO access to multiple AWS accounts when integrating with an on-premises Active Directory. AWS IAM Identity Center provides a centralized management experience, and its integration with AWS Directory Service (e.g., AD Connector or Managed Microsoft AD) simplifies the connection to the existing Active Directory, minimizing operational overhead for identity synchronization and access management. Option B (incorrect) represents an anti-pattern (ap-4.1-002) by creating IAM users for human access, which leads to significant operational overhead for managing credentials, password rotations, and permissions across multiple accounts. Option C (incorrect) is primarily designed for customer-facing applications and external users, not typically for internal workforce access to AWS accounts. While it can federate, it''s not the optimal solution for this specific enterprise workforce SSO scenario. Option D (incorrect) involves setting up direct SAML federation for each AWS account, which is more complex and requires more administrative effort compared to the centralized management offered by AWS IAM Identity Center.', 57, 'm_57_1', 1, NULL, NULL),
  ('mock_54_all_1775000123948', 'A mobile application allows users to upload photos to an Amazon S3 bucket. The application needs to authenticate users and grant them temporary, limited-privilege access to the S3 bucket without embedding AWS credentials directly into the application. The solution must be MOST secure.', '["Create an IAM user with programmatic access for each mobile application user and distribute their credentials securely.","Use Amazon Cognito User Pools for user authentication and Amazon Cognito Identity Pools to grant temporary AWS credentials via IAM roles.","Implement a custom authentication backend on an Amazon EC2 instance that issues temporary AWS credentials using AWS STS.","Configure an Amazon S3 bucket policy to allow anonymous uploads, then restrict access based on IP addresses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most secure and recommended approach for mobile applications. Amazon Cognito User Pools handle user authentication, and Amazon Cognito Identity Pools then federate these authenticated users to obtain temporary, limited-privilege AWS credentials via AWS STS. This eliminates the need to embed long-term credentials in the application, enhancing security. Option A (incorrect) represents an anti-pattern (ap-4.1-002) by creating IAM users for human access, which is not suitable for mobile applications due to the difficulty of securely distributing and rotating long-term credentials. Option C (incorrect) involves significant operational overhead to build and maintain a custom authentication backend, which Amazon Cognito provides as a managed service. Option D (incorrect) is highly insecure as it allows anonymous public access to the S3 bucket, which violates the principle of least privilege and data confidentiality, even with IP restrictions.', 57, 'm_57_1', 2, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company needs to grant a third-party auditing firm temporary, read-only access to specific Amazon S3 buckets in a dedicated audit AWS account. The access must be revocable and strictly limited to the auditing firm''s AWS account, preventing any other entity from assuming the role. Which approach ensures the MOST secure cross-account access?', '["Create an IAM user for the auditing firm in the audit account and share the credentials securely.","Configure a resource-based policy on each S3 bucket to grant access to the auditing firm''s AWS account ID.","Create an IAM role in the audit account with read-only S3 permissions and a trust policy that includes the auditing firm''s AWS account ID and an `sts:ExternalId` condition.","Establish an AWS Organizations Service Control Policy (SCP) that allows the auditing firm''s AWS account to access S3 buckets."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most secure cross-account access for a third party. Creating an IAM role with a trust policy that includes the auditing firm''s AWS account ID ensures only principals from that account can attempt to assume the role. Crucially, adding an `sts:ExternalId` condition prevents confused deputy attacks and ensures the third party must provide a unique identifier known only to them, making the role assumption strictly limited and auditable. Option A (incorrect) is an anti-pattern (ap-4.1-002) for human access, as it involves long-term credentials that are difficult to manage, rotate, and revoke, and does not provide the same level of security or control as role assumption. Option B (incorrect) is a valid method for cross-account access but does not offer the `sts:ExternalId` protection, making it less secure against potential confused deputy scenarios (ap-4.2-001). Option D (incorrect) is a preventive control that defines maximum permissions but does not grant access; it cannot be used to directly grant access to an external entity.', 57, 'm_57_1', 3, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security team wants to enforce that all IAM roles created within a specific Organizational Unit (OU) can only be assumed by principals that belong to the same AWS Organization. This is a preventive control to prevent unintended cross-organization access. Which method should be used?', '["Apply an IAM permission boundary to all IAM roles within the OU, restricting `iam:AssumeRole` to the organization.","Implement an IAM policy on each IAM role that denies `iam:AssumeRole` if the principal is not from the organization.","Use IAM Access Analyzer to identify and alert on any roles that allow cross-organization access.","Deploy an AWS Organizations Service Control Policy (SCP) at the OU level that denies `iam:AssumeRole` unless the `aws:PrincipalOrgID` condition key matches the organization''s ID."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective preventive control for this scenario. An AWS Organizations Service Control Policy (SCP) applied at the OU level can explicitly deny `iam:AssumeRole` actions unless the `aws:PrincipalOrgID` condition key matches the organization''s ID. This ensures that any role created within that OU cannot be assumed by principals outside the organization, regardless of the individual IAM role''s trust policy. Option A (incorrect) is not suitable because permission boundaries define the maximum permissions an IAM entity can have, but they do not prevent `iam:AssumeRole` itself or enforce organizational context during assumption. Option B (incorrect) requires manual implementation on each role, which is not scalable or preventive for new roles, and can be overridden by other policies. Option C (incorrect) is a detective control that identifies existing issues, but it does not prevent the creation of such roles or enforce the restriction proactively.', 57, 'm_57_1', 4, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company requires all AWS Management Console access for IAM users to be protected by Multi-Factor Authentication (MFA). They need a scalable solution that denies access if MFA is not used, with the LEAST administrative effort for enforcement.', '["Create an IAM policy that explicitly denies `aws:Administrators` group access to the console if `aws:MultiFactorAuthPresent` is false, and attach it to all IAM users.","Manually enable and configure MFA for each individual IAM user through the IAM console.","Implement an AWS Organizations Service Control Policy (SCP) at the root that denies `aws:SourceIp` if `aws:MultiFactorAuthPresent` is false.","Use AWS Config rules to detect non-MFA console logins and trigger remediation actions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is a scalable and effective way to enforce MFA for console access with minimal administrative effort. A single IAM policy can be created and attached to groups or directly to IAM users, denying console access (`*` for actions, `*` for resources) if the `aws:MultiFactorAuthPresent` condition key is false. This policy acts as a preventive control. Option B (incorrect) involves significant manual effort, especially for a large number of users, and is not scalable. Option C (incorrect) incorrectly uses `aws:SourceIp` instead of `aws:MultiFactorAuthPresent` and SCPs are typically used for broader organizational controls, while an IAM policy is more direct for IAM user enforcement within an account. Option D (incorrect) is a detective control that identifies non-compliant resources after the fact, rather than preventing the unauthorized access in the first place.', 57, 'm_57_1', 5, NULL, NULL),
  ('mock_54_all_1775000123948', 'A development team has an application running on Amazon EC2 instances that needs to interact with Amazon S3. For security best practices, the EC2 instances should receive temporary credentials without storing long-term AWS access keys. Which AWS service provides this capability?', '["AWS IAM Identity Center, by configuring an application assignment for the EC2 instances.","AWS Security Token Service (STS), through IAM roles for EC2 instances.","Amazon Cognito Identity Pools, by associating the EC2 instances with an identity pool.","AWS Directory Service, by creating a trust relationship between EC2 and the directory."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the standard and most secure way to provide temporary credentials to Amazon EC2 instances. By associating an IAM role with an EC2 instance, the instance can automatically receive temporary credentials from AWS STS, which are rotated regularly. This eliminates the need to store long-term access keys on the instance. Option A (incorrect) is designed for workforce users to access AWS accounts and applications, not for EC2 instances to obtain credentials. Option C (incorrect) is primarily used for authenticating external users (e.g., mobile/web apps) and granting them temporary AWS access, not for EC2 instances. Option D (incorrect) is used for directory services (like Active Directory) and user authentication, not for granting temporary AWS credentials to EC2 instances.', 57, 'm_57_1', 6, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company wants to enable federated access for its employees from an on-premises identity provider (IdP) to multiple AWS accounts. The solution should centralize access management and provide time-limited credentials, reducing the risk associated with long-term credentials. Which service is best suited for this requirement?', '["AWS IAM, by creating individual IAM users and configuring them with SAML federation.","Amazon Cognito, by setting up a User Pool and integrating it with the on-premises IdP.","AWS IAM Identity Center (successor to AWS SSO), by integrating with the on-premises IdP.","AWS Directory Service, by extending the on-premises directory to AWS."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary service for centralizing workforce access to multiple AWS accounts and applications, especially when federating with an on-premises identity provider. AWS IAM Identity Center provides a unified portal for users, manages permissions centrally, and issues time-limited credentials via AWS STS, aligning with security best practices. Option A (incorrect) involves creating IAM users, which is an anti-pattern (ap-4.1-002) for human access, as it requires managing long-term credentials per user per account, increasing administrative overhead and security risk. Option B (incorrect) is primarily designed for customer-facing applications and external users, not typically for internal workforce access to AWS accounts. Option D (incorrect) provides managed directory services but does not directly handle federated access to AWS accounts; it would be a component used by IAM Identity Center for integration, but not the complete solution itself.', 57, 'm_57_1', 7, NULL, NULL),
  ('mock_54_all_1775000123948', 'An application needs to assume an IAM role in a different account to perform a specific, sensitive operation. The security team requires that the assumed role''s permissions are further restricted to a subset of its original permissions for that particular session, adhering to the principle of LEAST privilege. How can this be achieved?', '["Use AWS STS `AssumeRole` with a session policy.","Create a new IAM role with reduced permissions for each specific sensitive operation.","Apply an IAM permission boundary to the target IAM role to restrict its maximum permissions.","Configure an AWS Organizations Service Control Policy (SCP) to limit the actions allowed by the assumed role."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the precise mechanism for restricting an assumed role''s permissions for a specific session. When calling AWS STS `AssumeRole`, you can pass a session policy, which acts as an inline policy that further limits the permissions of the temporary credentials issued. The effective permissions for the session are the intersection of the role''s identity policy and the session policy, ensuring least privilege for that specific operation. Option B (incorrect) would lead to an explosion of IAM roles, increasing administrative complexity and operational overhead, and is not suitable for dynamic, session-specific restriction. Option C (incorrect) defines the maximum permissions that an IAM role can ever grant, but it does not dynamically restrict permissions for a specific session. Option D (incorrect) is a preventive control at the organizational level that defines maximum permissions allowed within an account or OU, but it does not dynamically restrict permissions for an individual session of an assumed role.', 57, 'm_57_1', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_57_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A development team has an IAM policy allowing S3 `GetObject` on `arn:aws:s3:::my-bucket/*`. A separate Service Control Policy (SCP) in AWS Organizations explicitly denies `s3:GetObject` on `arn:aws:s3:::my-bucket/sensitive-data/*` for all accounts in the OU. A developer attempts to retrieve `s3://my-bucket/sensitive-data/file.txt`. What is the outcome?', '["Access is allowed because the identity-based policy grants the necessary permission.","Access is denied due to the explicit deny statement in the SCP, which takes precedence.","Access is allowed, but an alert is triggered due to the SCP violation.","Access is denied, but only if an IAM permission boundary also explicitly denies the action."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) accurately describes the IAM policy evaluation logic. An explicit deny in any policy (identity-based, resource-based, permission boundary, or SCP) always overrides any allow statement. In this scenario, the SCP''s explicit deny for `s3:GetObject` on `arn:aws:s3:::my-bucket/sensitive-data/*` will block the developer''s attempt, regardless of the allow statement in their identity-based policy. This is a common anti-pattern (ap-4.1-001) where users misunderstand the precedence of explicit denies. Option A (incorrect) is wrong because an explicit deny always wins. Option C (incorrect) is incorrect; SCPs are preventive controls, not alerting mechanisms for allowed actions. Option D (incorrect) is wrong; an explicit deny in an SCP is sufficient to deny access, a permission boundary is not required for this specific denial.', 57, 'm_57_2', 9, NULL, NULL),
  ('mock_54_all_1775000123948', 'A data analytics application running in Account A needs to read data from an Amazon S3 bucket in Account B. The security team wants to grant this access with the LEAST operational overhead, ensuring the data remains in Account B and is accessed directly by the application''s IAM role.', '["Create an IAM role in Account B with S3 read permissions and configure Account A''s application to assume this role using AWS STS.","Attach a resource-based policy to the S3 bucket in Account B, granting `s3:GetObject` to the specific IAM role ARN from Account A.","Duplicate the S3 data from Account B into a new bucket in Account A and grant local access.","Configure an AWS Organizations Service Control Policy (SCP) to allow cross-account S3 access between Account A and Account B."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most straightforward and least overhead approach for this scenario. A resource-based policy (S3 bucket policy) directly grants permissions to a principal (the IAM role from Account A) to access the resource (the S3 bucket in Account B). This avoids the complexity of role assumption and temporary credentials for the application itself, as the S3 service evaluates the policy directly. Option A (incorrect) involves cross-account role assumption, which is a valid pattern but introduces more complexity (e.g., managing temporary credentials) compared to a direct resource policy for S3 access, thus increasing operational overhead. Option C (incorrect) involves duplicating data, which increases storage costs, introduces data synchronization challenges, and is not the most cost-effective or secure method. Option D (incorrect) is a preventive control that defines maximum permissions; it does not grant access itself.', 57, 'm_57_2', 10, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company wants to implement attribute-based access control (ABAC) for its Amazon EC2 instances. Developers should only be able to start or stop EC2 instances that are tagged with their respective department (e.g., `department:finance` for finance developers). Which IAM policy condition key should be used to enforce this ABAC strategy?', '["`aws:RequestTag/department` to check the tag on the API request.","`aws:PrincipalTag/department` to check the tag on the requesting IAM principal.","`aws:ResourceTag/department` to check the tag on the target EC2 instance.","A combination of `aws:PrincipalTag/department` and `aws:ResourceTag/department` to ensure matching tags."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the appropriate way to implement ABAC for this scenario. To ensure a developer can only act on resources tagged with their department, the IAM policy must check both the tag on the requesting principal (`aws:PrincipalTag/department`) and the tag on the target resource (`aws:ResourceTag/department`). This ensures that the principal''s department tag matches the resource''s department tag for the action to be allowed. Option A (incorrect) checks tags in the API request, which is not directly used for matching principal tags to resource tags for ABAC. Option B (incorrect) only checks the tag on the requesting principal; it doesn''t ensure the target resource has a matching tag. Option C (incorrect) only checks the tag on the target resource; it doesn''t ensure the requesting principal has a matching tag.', 57, 'm_57_2', 11, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security administrator is reviewing an existing IAM policy and suspects it might grant more permissions than intended. They need to quickly determine the effective permissions granted by this policy when combined with other identity-based and resource-based policies, without impacting production environments.', '["Review AWS CloudTrail logs to see what actions have been performed by principals using this policy.","Use IAM Access Analyzer to identify any external access granted by the policy.","Utilize the IAM policy simulator to test the policy against specific actions and resources for a given principal.","Create a temporary IAM user with the policy attached and attempt various actions in a sandbox environment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the ideal tool for this scenario. The IAM policy simulator allows a security administrator to test and understand the effective permissions of an IAM policy in combination with other identity-based policies, resource-based policies, permission boundaries, and SCPs. It provides a quick and safe way to determine what actions are allowed or denied without affecting production. Option A (incorrect) shows what actions *were* performed, not what *can be* performed, and doesn''t help in proactively identifying over-permissioned policies. Option B (incorrect) focuses on external access, not necessarily on over-permissioning within the account for internal principals. Option D (incorrect) is a manual and time-consuming process that requires setting up a sandbox and could still lead to unintended actions if not carefully managed, whereas the policy simulator is a safe, virtual environment.', 57, 'm_57_2', 12, NULL, NULL),
  ('mock_54_all_1775000123948', 'A new AWS service-linked role is automatically created when a specific AWS service is enabled. The security team needs to understand the exact permissions granted to this role to ensure it adheres to the principle of least privilege and does not introduce unnecessary security risks. What is the most reliable way to determine these permissions?', '["Inspect the service-linked role''s attached policies in the IAM console and modify them if necessary.","Review the AWS documentation for the specific service-linked role, as its permissions are predefined and managed by AWS.","Use IAM Access Analyzer to evaluate the service-linked role''s access to resources.","Run the IAM policy simulator against the service-linked role to determine its effective permissions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most reliable way to understand service-linked role permissions. Service-linked roles are unique IAM roles that are linked directly to an AWS service. They are predefined by the service and include all the permissions that the service requires to call other AWS services on your behalf. Their permissions cannot be modified by users, and they are automatically created and deleted by the linked service. Therefore, consulting the official AWS documentation for the specific service-linked role is the authoritative source for its permissions. Option A (incorrect) is not possible because service-linked role policies cannot be modified by users. Option C (incorrect) can evaluate access but doesn''t provide the foundational definition of the role''s permissions. Option D (incorrect) can simulate permissions but the source of truth for service-linked role permissions is the AWS documentation.', 57, 'm_57_2', 13, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company wants to prevent any IAM user or role within a specific AWS account from creating Amazon S3 buckets that are publicly accessible. This must be a preventative control at the account level, ensuring that no bucket can be made public upon creation or later modification. Which solution is MOST effective?', '["Implement an AWS Organizations Service Control Policy (SCP) at the account level that explicitly denies `s3:PutBucketPublicAccessBlock` and `s3:PutBucketAcl` if public access is attempted.","Create an IAM permission boundary for all IAM users and roles in the account, denying `s3:PutBucketPublicAccessBlock`.","Configure an Amazon S3 bucket policy on each new bucket to explicitly deny public access.","Use AWS Config rules to detect publicly accessible S3 buckets and automatically remediate them."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective preventive control for this scenario. An AWS Organizations Service Control Policy (SCP) can be applied at the account level to explicitly deny actions like `s3:PutBucketPublicAccessBlock` (which manages the block public access settings) and `s3:PutBucketAcl` (which can grant public access) if conditions for public access are met. This ensures that no principal within the account can make an S3 bucket publicly accessible, either at creation or later. Option B (incorrect) is less effective because permission boundaries define the maximum permissions a principal can have, but an SCP provides a stronger, account-wide preventive guardrail that cannot be circumvented by individual IAM policies. Option C (incorrect) is reactive and requires a bucket to be created first, then a policy applied, which doesn''t prevent public access at creation. Option D (incorrect) is a detective control that identifies non-compliant resources after they are created, rather than preventing their creation or modification to be public.', 57, 'm_57_2', 14, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security team needs to grant cross-account access to a third-party analytics vendor. The vendor will assume an IAM role in the company''s AWS account to access specific Amazon S3 data. To prevent confused deputy attacks and ensure the access is strictly limited to the vendor''s specific AWS account, which IAM trust policy condition should be used?', '["`aws:SourceIp` to restrict access to the vendor''s IP address range.","`sts:ExternalId` to require the vendor to provide a unique identifier when assuming the role.","`aws:PrincipalOrgID` to ensure the principal belongs to the company''s AWS Organization.","`aws:RequestedRegion` to limit the region where the role can be assumed."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate condition to prevent confused deputy attacks and strictly limit cross-account access to a specific third-party vendor. The `sts:ExternalId` condition key in the IAM role''s trust policy requires the assuming entity (the third-party vendor) to provide a unique identifier that only they know. This ensures that the role assumption request genuinely originates from the intended third party and not from another entity that might trick the vendor into assuming the role. This directly addresses the anti-pattern (ap-4.2-001) of granting cross-account access via broad trust policies without condition keys. Option A (incorrect) restricts by IP address, which can be dynamic for cloud providers and doesn''t prevent a confused deputy attack if the attacker is within the allowed IP range. Option C (incorrect) is used for internal cross-account access within the same AWS Organization, not for third-party vendors. Option D (incorrect) limits the region but does not prevent unauthorized entities from assuming the role.', 57, 'm_57_2', 15, NULL, NULL);

