INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A large enterprise with multiple development teams requires a secure, scalable, and standardized way to provision new AWS accounts. The security team needs to ensure that every new account automatically adheres to a baseline set of security policies, including mandatory logging and specific network configurations, with the LEAST operational overhead for the central security team.', '["Implement AWS Control Tower to automate the setup of a multi-account landing zone, including account vending and preventive guardrails via AWS Organizations SCPs.","Manually create new AWS accounts for each team and then use AWS CloudFormation StackSets to deploy baseline security configurations to each account.","Develop a custom script using the AWS SDK to create new accounts and then apply AWS Config rules to detect non-compliance after account creation.","Utilize AWS Service Catalog to allow teams to request pre-approved resource templates, while relying on individual account administrators to configure account-level security."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most automated and integrated solution for multi-account governance. AWS Control Tower automates the setup of a secure multi-account landing zone, including account vending through AWS Service Catalog and enforcing preventive and detective guardrails using AWS Organizations SCPs and AWS Config rules. This significantly reduces operational overhead for the central security team by ensuring new accounts are born compliant. Option B (incorrect) involves manual account creation, which increases operational overhead and is prone to human error, failing the ''LEAST operational overhead'' constraint. While CloudFormation StackSets can deploy configurations, the initial account setup and ongoing governance are less automated than Control Tower. Option C (incorrect) relies on a custom script for account creation, which introduces maintenance overhead, and using AWS Config rules for detection means issues are found after the fact (detective control), rather than prevented at creation, which is less secure and more reactive. Option D (incorrect) focuses on resource provisioning within accounts but does not address the automated, secure provisioning and baseline governance of the accounts themselves. Relying on individual account administrators for account-level security introduces inconsistency and potential security gaps, failing the ''LEAST operational overhead'' and ''standardized'' requirements.', 59, 'm_59_1', 1, NULL, NULL),
  ('mock_54_all_1775000123948', 'A global financial institution needs to enforce strict, mandatory security policies across all AWS accounts within its organization. Specifically, they must prevent any account administrator from disabling AWS CloudTrail logging or modifying Amazon S3 bucket policies to allow public read/write access. The solution must be preventive and apply to all current and future accounts.', '["Deploy AWS Config rules to all accounts to detect non-compliant CloudTrail and S3 configurations, and trigger AWS Lambda functions for remediation.","Implement Service Control Policies (SCPs) in AWS Organizations to deny actions that disable CloudTrail or modify S3 bucket policies for public access.","Use AWS CloudFormation StackSets to deploy IAM policies to each account that restrict CloudTrail and S3 access, and enable drift detection.","Configure Amazon Security Hub to aggregate findings related to CloudTrail and S3 misconfigurations, and use AWS Audit Manager for compliance reporting."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution for enforcing preventive, mandatory security policies across an entire AWS Organization. Service Control Policies (SCPs) allow you to centrally manage permissions for all accounts in your organization, acting as guardrails that prevent specified actions, even by the root user of a member account. This ensures that actions like disabling CloudTrail or allowing public S3 access are explicitly denied organization-wide. Option A (incorrect) uses AWS Config rules, which are detective controls; they identify non-compliance after it has occurred. While remediation can be automated, it does not prevent the action from happening in the first place, which is crucial for strict, mandatory policies. Option C (incorrect) involves deploying IAM policies via CloudFormation StackSets. While this can enforce restrictions, IAM policies are identity-based or resource-based and can potentially be overridden or modified by administrators with sufficient permissions, especially if not coupled with SCPs. Drift detection is detective, not preventive. Option D (incorrect) focuses on aggregating security findings and compliance reporting, which are detective and audit controls. These are important for visibility and evidence collection but do not prevent the unwanted actions from occurring.', 59, 'm_59_1', 2, NULL, NULL),
  ('mock_54_all_1775000123948', 'A large software company operates in multiple AWS accounts across several AWS Regions. The security operations center (SOC) needs a unified view of security findings from various AWS services, such as Amazon GuardDuty, AWS Config, and Amazon Inspector, to identify and prioritize security risks centrally. The solution should minimize the effort required to aggregate findings.', '["Configure individual Amazon CloudWatch Alarms in each account and Region to send notifications to a central Amazon SNS topic.","Manually export security findings from each service in every account and Region, then consolidate them into a custom dashboard.","Enable Amazon Security Hub in all accounts and Regions, then configure cross-account and cross-Region aggregation to a central Security Hub account.","Deploy AWS Config conformance packs to each account and Region, and then use AWS Audit Manager to collect compliance evidence."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most efficient and integrated solution for centralizing security findings across multiple accounts and Regions. Amazon Security Hub is designed to aggregate, organize, and prioritize security alerts and findings from various AWS services (like GuardDuty, Config, Inspector) and even third-party security products. Its cross-account and cross-Region aggregation features allow the SOC to consolidate all findings into a single designated administrator account, providing a unified view with minimal management overhead. Option A (incorrect) would require significant manual configuration and maintenance of CloudWatch Alarms and SNS topics across all accounts and Regions, leading to high operational overhead and a fragmented view of findings. Option B (incorrect) is a manual, highly inefficient, and error-prone process that would not scale and would provide delayed insights, failing the requirement for minimizing effort. Option D (incorrect) focuses on compliance assessment and evidence collection using AWS Config conformance packs and AWS Audit Manager. While valuable for compliance, it does not provide a centralized, real-time aggregation and prioritization of diverse security findings from multiple services like Security Hub does.', 59, 'm_59_1', 3, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A healthcare organization must comply with HIPAA regulations, requiring continuous monitoring of all AWS resources for specific security configurations, such as encryption at rest for sensitive data and restricted network access. They need an automated solution to assess compliance against these custom rules and identify non-compliant resources promptly.', '["Manually review resource configurations periodically using the AWS Management Console and generate reports.","Implement AWS Config with custom rules to continuously evaluate resource configurations against HIPAA requirements and report non-compliance.","Use Amazon Security Hub to aggregate findings from various AWS services and manually correlate them with HIPAA controls.","Develop custom scripts to query AWS APIs for resource configurations and store the results in Amazon S3 for later analysis."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate solution for continuous compliance monitoring against custom rules. AWS Config allows you to define custom rules (using AWS Lambda functions or managed rules) to evaluate whether your AWS resource configurations comply with your internal policies or regulatory standards like HIPAA. It continuously records configuration changes and assesses them against your rules, reporting non-compliant resources promptly. Option A (incorrect) is a manual, labor-intensive, and error-prone process that does not scale and cannot provide continuous monitoring, making it unsuitable for stringent compliance requirements. Option C (incorrect) aggregates findings from various services, which is useful for overall security posture, but it requires manual correlation with specific HIPAA controls and doesn''t provide the direct, continuous evaluation against custom rules that AWS Config offers. Option D (incorrect) involves developing and maintaining custom scripts, which introduces significant operational overhead, potential for errors, and lacks the integrated reporting and remediation capabilities of AWS Config.', 59, 'm_59_3', 4, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company is preparing for an annual PCI DSS audit and needs to demonstrate continuous compliance with various security controls across their AWS environment. They require an automated way to collect evidence, map it to specific PCI DSS requirements, and generate audit-ready reports, minimizing manual effort during the audit process.', '["Use AWS Config to record all resource configuration changes and manually compile a report from the configuration history.","Configure Amazon Security Hub to aggregate security findings and manually map them to PCI DSS controls for reporting.","Implement AWS Audit Manager, selecting the PCI DSS framework, to automate evidence collection and generate audit-ready reports.","Create custom dashboards in Amazon CloudWatch to monitor resource metrics and manually extract data for audit purposes."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed for automating evidence collection and preparing for audits like PCI DSS. AWS Audit Manager helps you continuously audit your AWS usage to simplify how you assess risk and compliance with regulations and industry standards. It provides pre-built frameworks (including PCI DSS) that automatically collect evidence from various AWS services, map it to control requirements, and generate audit-ready reports, significantly reducing manual effort. Option A (incorrect) uses AWS Config for configuration recording, which is a foundational component, but it doesn''t automate the mapping to PCI DSS controls or the generation of audit-ready reports in the way Audit Manager does. Manual compilation would be labor-intensive. Option B (incorrect) aggregates security findings, which is valuable for security posture, but it doesn''t automate the evidence collection and mapping to audit frameworks like PCI DSS. Manual mapping would still be required. Option D (incorrect) focuses on operational monitoring with CloudWatch, which is not designed for compliance evidence collection or audit reporting against specific regulatory frameworks.', 59, 'm_59_3', 5, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security team manages a multi-account AWS environment and needs a centralized dashboard to view, prioritize, and manage security findings from various AWS services like Amazon GuardDuty, AWS Config, and AWS Firewall Manager. They want to ensure that all findings are consolidated into a single pane of glass for efficient security operations.', '["Develop a custom application to ingest logs from AWS CloudTrail and process them to identify security events.","Set up Amazon CloudWatch Dashboards in each account to monitor security-related metrics and logs.","Use AWS Config conformance packs to assess compliance across accounts and generate reports.","Enable Amazon Security Hub in all accounts and configure it as the central security findings aggregator."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the purpose-built service for centralizing security findings. Amazon Security Hub aggregates security findings from various AWS services (like GuardDuty, Config, Inspector, Firewall Manager) and even third-party security products into a single, comprehensive view. It normalizes these findings into a standardized format (AWS Security Finding Format - ASFF), allowing for easier analysis, prioritization, and management from a central dashboard. Option A (incorrect) involves building a custom solution, which introduces significant development and maintenance overhead and is less efficient than using a managed service like Security Hub. Option B (incorrect) would result in fragmented dashboards across multiple accounts, failing the ''centralized dashboard'' requirement. Option C (incorrect) focuses on compliance assessment and reporting using AWS Config conformance packs. While related to security, it doesn''t provide the comprehensive aggregation and management of diverse security findings from multiple services that Security Hub offers.', 59, 'm_59_3', 6, NULL, NULL),
  ('mock_54_all_1775000123948', 'A compliance officer needs to ensure that all Amazon S3 buckets across their multi-account AWS environment have server-side encryption enabled and are not publicly accessible. They require continuous, automated monitoring and reporting of these specific configurations to meet internal security policies.', '["Implement AWS Config managed rules for S3 bucket encryption and public access, deploying them across all accounts.","Manually review each S3 bucket''s properties in the AWS Management Console on a weekly basis.","Use AWS CloudFormation StackSets to deploy S3 bucket policies to deny public access, and rely on IAM policies for encryption enforcement.","Configure Amazon Security Hub to aggregate findings from Amazon GuardDuty, which detects unusual S3 access patterns."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most effective and automated solution for continuous monitoring of specific S3 configurations. AWS Config allows you to deploy managed rules (e.g., `s3-bucket-server-side-encryption-enabled`, `s3-bucket-public-read-prohibited`) across multiple accounts. These rules continuously evaluate S3 bucket configurations against the desired state and report non-compliant resources, fulfilling the requirement for automated monitoring and reporting. Option B (incorrect) is a manual, inefficient, and error-prone approach that cannot provide continuous monitoring or scale effectively across a multi-account environment. Option C (incorrect) uses CloudFormation StackSets to deploy S3 bucket policies, which is a good preventive measure, but it doesn''t provide continuous, automated monitoring and reporting of the actual configuration state like AWS Config does. IAM policies for encryption enforcement are also preventive but lack continuous compliance assessment. Option D (incorrect) uses Amazon Security Hub and GuardDuty, which are valuable for detecting threats and aggregating findings, but GuardDuty primarily focuses on anomalous activity rather than continuous configuration compliance of S3 buckets against specific rules.', 59, 'm_59_3', 7, NULL, NULL),
  ('mock_54_all_1775000123948', 'An organization needs to demonstrate adherence to the CIS AWS Foundations Benchmark across all its AWS accounts for an upcoming security audit. They require an automated method to assess compliance against this benchmark and generate a consolidated report, minimizing the manual effort for the security and compliance teams.', '["Manually audit each AWS account against the CIS Benchmark checklist and compile results into a spreadsheet.","Deploy AWS Config conformance packs for the CIS AWS Foundations Benchmark across all accounts and aggregate findings in a central account.","Configure Amazon Security Hub to ingest findings from various services and manually map them to CIS Benchmark controls.","Use AWS Audit Manager to collect evidence for custom controls that mirror the CIS Benchmark requirements."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most direct and automated approach for assessing compliance against the CIS AWS Foundations Benchmark. AWS Config conformance packs allow you to deploy a collection of AWS Config rules and remediation actions as a single entity. AWS provides managed conformance packs, including one for the CIS AWS Foundations Benchmark. Deploying this across all accounts and aggregating findings (e.g., via a central AWS Config aggregator) provides an automated, consolidated compliance report. Option A (incorrect) is a manual, time-consuming, and error-prone process that does not scale and is not suitable for continuous compliance. Option C (incorrect) uses Amazon Security Hub to aggregate findings, which is useful for overall security posture, but it requires manual mapping of these findings to the specific CIS Benchmark controls, which increases manual effort. While Security Hub *does* integrate with CIS benchmarks, Config conformance packs are specifically designed for continuous assessment against these benchmarks. Option D (incorrect) uses AWS Audit Manager, which is excellent for audit evidence collection. While you *could* create custom controls to mirror the CIS Benchmark, using a pre-built AWS Config conformance pack is more direct and less effort for this specific requirement.', 59, 'm_59_3', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A security team is concerned about potential misconfigurations in their multi-account AWS environment that could expose sensitive data. They need a way to proactively identify resources that do not meet their internal security standards, such as unencrypted databases or publicly accessible storage buckets, and get a centralized view of these compliance issues.', '["Rely solely on AWS CloudTrail logs to detect API calls related to resource creation and manually analyze them for security gaps.","Implement AWS Organizations Service Control Policies (SCPs) to prevent the creation of non-compliant resources.","Deploy AWS Config conformance packs across all accounts to continuously assess resource configurations against security best practices and aggregate findings in Amazon Security Hub.","Conduct quarterly manual security audits by reviewing resource configurations in each account''s AWS Management Console."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a robust, proactive, and centralized solution for identifying misconfigurations. AWS Config conformance packs allow the security team to define and deploy a set of AWS Config rules (which can include checks for encryption, public access, etc.) across multiple accounts. These rules continuously assess resource configurations. Aggregating these findings in Amazon Security Hub provides a centralized view of compliance issues and security posture across the entire multi-account environment. Option A (incorrect) relies on CloudTrail logs, which are primarily for auditing API activity. While useful for forensics, analyzing raw logs for proactive misconfiguration detection is inefficient and reactive. Option B (incorrect) uses SCPs, which are excellent for *preventing* non-compliant resource creation. However, the question asks to *identify* existing misconfigurations and get a centralized view, which is a detective control. SCPs prevent future issues but don''t identify current ones. Option D (incorrect) is a manual, infrequent, and unscalable approach that would miss real-time misconfigurations and is highly inefficient for a multi-account environment.', 59, 'm_59_4', 9, NULL, NULL),
  ('mock_54_all_1775000123948', 'An organization needs to ensure that all new Amazon EC2 instances launched by development teams adhere to specific security baselines, including using approved Amazon Machine Images (AMIs) and being associated with specific security groups. The solution must allow developers to provision instances quickly while ensuring compliance preventatively.', '["Provide developers with direct access to the Amazon EC2 console and instruct them to follow a manual checklist for security configurations.","Use AWS CloudFormation templates to define the EC2 instance configurations and require developers to manually deploy these templates.","Publish pre-approved EC2 instance configurations as products in AWS Service Catalog, allowing developers to self-provision compliant instances.","Implement AWS Config rules to detect non-compliant EC2 instances after they are launched and trigger automated remediation."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution for enabling self-service provisioning of compliant resources. AWS Service Catalog allows organizations to create and manage catalogs of IT services that are approved for use on AWS. By publishing pre-approved EC2 instance configurations (defined by AWS CloudFormation templates) as Service Catalog products, developers can provision instances quickly and easily, knowing they automatically adhere to the required security baselines. This provides preventive compliance. Option A (incorrect) relies on manual processes, which are prone to human error, inconsistent, and do not guarantee compliance. Option B (incorrect) requires developers to manually deploy CloudFormation templates, which is better than console access but still lacks the self-service, governed experience of Service Catalog, and doesn''t inherently prevent deviations without additional controls. Option D (incorrect) uses AWS Config rules, which are detective controls. They identify non-compliant instances *after* they are launched, requiring remediation, which is not a preventive approach.', 59, 'm_59_4', 10, NULL, NULL),
  ('mock_54_all_1775000123948', 'A compliance team needs to continuously assess their AWS environment against a custom set of security policies that are unique to their industry. They also need to generate detailed reports that map specific resource configurations and changes to these custom policies for internal and external auditors. The solution must be highly automated.', '["Utilize AWS Config custom rules to continuously evaluate resource configurations against the custom policies and use AWS Audit Manager to collect and organize evidence.","Deploy AWS Organizations Service Control Policies (SCPs) to enforce the custom security policies across all accounts, preventing non-compliant actions.","Configure Amazon Security Hub to aggregate findings from various AWS services and manually correlate them with the custom security policies.","Develop a custom application that periodically queries AWS APIs for resource configurations and generates reports based on predefined logic."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the best combination for continuous assessment against custom policies and automated evidence collection. AWS Config custom rules (using AWS Lambda) allow you to define specific logic to evaluate resource configurations against your unique security policies. AWS Audit Manager can then be configured to collect evidence from AWS Config (and other services), map it to your custom controls, and generate audit-ready reports, significantly automating the compliance process. Option B (incorrect) uses SCPs, which are preventive controls. While SCPs enforce policies, they do not provide continuous assessment and reporting of the current compliance state of resources against those policies, which is what the question asks for. Option C (incorrect) aggregates findings, but requires manual correlation with custom policies, which is not fully automated for reporting. Option D (incorrect) involves building and maintaining a custom application, which introduces significant development and operational overhead compared to using managed AWS services designed for this purpose.', 59, 'm_59_4', 11, NULL, NULL),
  ('mock_54_all_1775000123948', 'After a recent security incident, a company''s leadership mandates that all AWS accounts must enforce multi-factor authentication (MFA) for the root user and that all Amazon S3 buckets must have server-side encryption enabled by default. They need a solution that applies these best practices across all existing and future accounts with minimal administrative overhead.', '["Manually log into each AWS account and enable MFA for the root user, then configure S3 bucket policies for encryption.","Implement AWS Control Tower''s preventive and detective guardrails, including those for root user MFA and S3 bucket encryption, across the organization.","Deploy AWS CloudFormation StackSets to enforce IAM policies for MFA and S3 bucket policies for encryption in all accounts.","Use AWS Config rules to detect non-compliance for root user MFA and S3 encryption, and then manually remediate identified issues."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most comprehensive and automated solution. AWS Control Tower provides strong governance capabilities, including preventive and detective guardrails. It offers specific guardrails to ensure root user MFA is enabled and S3 buckets are encrypted by default, applying these across all accounts in the organization with minimal administrative overhead. Option A (incorrect) is a manual, unscalable, and error-prone approach that does not meet the ''minimal administrative overhead'' requirement for a multi-account environment. Option C (incorrect) uses CloudFormation StackSets to deploy IAM policies and S3 bucket policies. While effective for deployment, it requires more manual management than Control Tower''s integrated guardrails and doesn''t provide the same level of preventive enforcement for root user MFA or the continuous monitoring that Control Tower offers. Option D (incorrect) uses AWS Config rules, which are detective controls. They identify non-compliance after it occurs, requiring manual remediation, which is not a preventive approach and increases administrative overhead.', 59, 'm_59_4', 12, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security operations center (SOC) needs to efficiently identify and prioritize security findings from various AWS services, such as Amazon GuardDuty, AWS Config, and AWS IAM Access Analyzer, across all accounts in their AWS Organization. They require a single, centralized console to view and manage these findings.', '["Create custom Amazon CloudWatch dashboards in each AWS account to display security metrics and alarms.","Develop a custom data lake solution to ingest security logs from all accounts and perform analysis.","Enable Amazon Security Hub across all accounts and configure cross-account aggregation to a central administrator account.","Utilize AWS Audit Manager to collect evidence of compliance with security best practices for all accounts."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary service designed for this purpose. Amazon Security Hub provides a comprehensive view of your security posture across all your AWS accounts. It automatically aggregates, normalizes, and prioritizes security findings from various AWS services and partner solutions into a single, centralized console. Cross-account aggregation allows findings from all member accounts to be sent to a designated administrator account for unified management. Option A (incorrect) would result in fragmented views across multiple accounts, failing the ''single, centralized console'' requirement. Option B (incorrect) involves significant development and maintenance overhead for a custom solution, which is less efficient than using a managed service like Security Hub. Option D (incorrect) is focused on audit evidence collection and compliance reporting, not on real-time aggregation and prioritization of diverse security findings for operational security management.', 59, 'm_59_4', 13, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775000123948', 'A development team needs to deploy a standardized web application stack, including Amazon EC2 instances, Amazon RDS databases, and Amazon S3 buckets, across multiple AWS accounts for different environments (dev, test, prod). The security team requires that all deployed resources adhere to predefined security configurations, such as specific encryption settings and network access rules. The solution must enable self-service provisioning while ensuring compliance.', '["Provide developers with direct access to the AWS Management Console in each account and a checklist of security configurations to follow.","Use AWS CloudFormation StackSets to deploy the application stack to all accounts, and manually verify security configurations post-deployment.","Implement AWS Config rules to detect non-compliant resources after deployment and trigger automated remediation.","Publish the standardized web application stack as an AWS Service Catalog product, allowing developers to self-provision compliant stacks."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective way to enable self-service provisioning of compliant resources. AWS Service Catalog allows organizations to create and manage catalogs of IT services that are approved for use on AWS. By publishing the standardized web application stack (defined by AWS CloudFormation templates) as a Service Catalog product, developers can provision the entire stack quickly and easily, knowing it automatically adheres to the required security configurations. This approach ensures preventive compliance. Option A (incorrect) relies on manual processes, which are prone to human error, inconsistent, and do not guarantee compliance, especially across multiple accounts and teams. Option B (incorrect) uses CloudFormation StackSets for deployment, which is good for consistency, but it still requires manual verification of security configurations post-deployment, which is not fully automated or preventive. Option C (incorrect) uses AWS Config rules, which are detective controls. They identify non-compliant resources *after* they are deployed, requiring remediation, which is not a preventive approach and introduces a window of vulnerability.', 59, 'm_59_2', 14, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security engineer needs to deploy a common set of security configurations, such as specific IAM roles, Amazon S3 bucket policies, and AWS Key Management Service (AWS KMS) key policies, consistently across all AWS accounts within a specific Organizational Unit (OU). Furthermore, these configurations must be immutable by individual account administrators to prevent unauthorized changes.', '["Utilize AWS CloudFormation StackSets to deploy the security configurations to all accounts in the OU, coupled with AWS Organizations Service Control Policies (SCPs) to prevent modification.","Deploy AWS Config conformance packs to each account in the OU to detect any deviations from the desired security configurations.","Manually log into each account in the OU and configure the security settings, then enable AWS CloudTrail for auditing.","Provide pre-approved AWS Service Catalog products for security configurations and rely on account administrators to provision them."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most robust solution for consistent, immutable deployment. AWS CloudFormation StackSets allow you to deploy a common CloudFormation template across multiple accounts and Regions. By combining this with AWS Organizations Service Control Policies (SCPs), you can prevent individual account administrators from modifying or deleting the deployed resources, ensuring immutability and consistent enforcement. Option B (incorrect) uses AWS Config conformance packs, which are detective controls. They detect deviations after they occur but do not prevent unauthorized changes, failing the ''immutable'' requirement. Option C (incorrect) is a manual, unscalable, and error-prone approach that does not ensure consistency or immutability. Option D (incorrect) uses AWS Service Catalog, which is excellent for self-service provisioning, but it relies on account administrators to provision the products and does not inherently prevent them from modifying the resulting resources unless additional preventive controls like SCPs are also in place.', 59, 'm_59_2', 15, NULL, NULL),
  ('mock_54_all_1775000123948', 'A company uses AWS CloudFormation to provision its infrastructure. The security team needs to ensure that all deployed resources remain compliant with the organization''s security baseline over time and wants to be immediately notified of any unauthorized changes or configuration drift from the original CloudFormation templates.', '["Implement AWS Organizations Service Control Policies (SCPs) to prevent any resource configuration changes.","Enable AWS CloudFormation drift detection on all relevant stacks and integrate it with Amazon EventBridge to trigger notifications upon detection.","Configure AWS Config rules to continuously monitor resource configurations and compare them against a manually defined desired state.","Rely on Amazon CloudWatch Logs to analyze API calls for unauthorized modifications and set up alarms for suspicious activity."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the requirement for detecting configuration drift from CloudFormation templates. AWS CloudFormation drift detection allows you to identify when the actual state of stack resources differs from their expected state in the CloudFormation template. Integrating this with Amazon EventBridge allows for automated notifications (e.g., via Amazon SNS) or actions when drift is detected, ensuring immediate awareness of unauthorized changes. Option A (incorrect) uses SCPs, which are preventive controls to *prevent* changes. While valuable, they don''t *detect* drift from a CloudFormation template if a change was made through a permitted API call outside of CloudFormation (e.g., if an SCP allowed it, but the CloudFormation template didn''t specify it). Option C (incorrect) uses AWS Config rules, which can detect configuration changes. However, for changes specifically related to CloudFormation stacks, drift detection is more precise as it compares against the template''s defined state, whereas Config rules often compare against a general desired state. Option D (incorrect) relies on analyzing CloudWatch Logs (from CloudTrail), which is a reactive and labor-intensive approach for detecting specific configuration drift compared to the purpose-built CloudFormation drift detection feature.', 59, 'm_59_2', 16, NULL, NULL),
  ('mock_54_all_1775000123948', 'A security architect needs to ensure that all new Amazon S3 buckets created by developers automatically have server-side encryption enabled and are not publicly accessible. This must be enforced preventatively, without requiring developers to manually configure these settings, and apply across all accounts in the organization.', '["Deploy AWS Config rules to detect non-compliant S3 buckets and trigger automated remediation via AWS Lambda functions.","Provide developers with a standard AWS CloudFormation template for S3 buckets that includes encryption and private access settings, and require them to use it.","Utilize AWS Service Catalog to offer a pre-approved S3 bucket product with enforced encryption and private access, combined with AWS Organizations Service Control Policies (SCPs) to prevent deviations.","Implement Amazon Security Hub to aggregate findings related to unencrypted or public S3 buckets and alert the security team."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most robust preventive solution. AWS Service Catalog allows developers to provision pre-approved S3 bucket products that are configured with encryption and private access by default. Combining this with AWS Organizations Service Control Policies (SCPs) ensures that even if a developer attempts to modify the bucket to be non-compliant after creation, or tries to create a non-compliant bucket outside of Service Catalog, the SCPs will prevent those actions. This provides both ease of use for developers and strong preventive enforcement. Option A (incorrect) uses AWS Config rules, which are detective controls. They identify non-compliance after it has occurred, requiring remediation, which is not a preventive approach. Option B (incorrect) relies on developers to *use* a standard template, but it doesn''t prevent them from making manual changes or using non-compliant methods. It lacks the strong preventive enforcement. Option D (incorrect) uses Amazon Security Hub, which is a detective control for aggregating findings and alerting, but it does not prevent the creation of non-compliant S3 buckets.', 59, 'm_59_2', 17, NULL, NULL),
  ('mock_54_all_1775000123948', 'An enterprise needs to roll out an updated security baseline for Amazon EC2 instances, including a new IAM instance profile and specific Amazon EBS encryption settings, to hundreds of existing instances across dozens of AWS accounts. The deployment must be consistent, automated, and allow for central management of the rollout process.', '["Manually update each EC2 instance''s IAM role and EBS encryption settings in every AWS account.","Develop custom scripts to iterate through all accounts and instances, applying the new configurations via AWS SDK.","Use AWS CloudFormation StackSets to deploy CloudFormation templates that update the EC2 instance profiles and EBS encryption settings across all target accounts.","Implement AWS Config rules to detect non-compliant EC2 instances and trigger AWS Lambda functions to remediate them."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) is the most effective and scalable solution for consistent, automated deployment of updates across a large multi-account environment. AWS CloudFormation StackSets allow you to define a CloudFormation template for the updated security baseline (e.g., new IAM instance profile, EBS encryption settings) and then deploy it to multiple target accounts and Regions simultaneously from a central administrator account. This ensures consistency and central management. Option A (incorrect) is a manual, highly inefficient, and error-prone approach that does not scale for hundreds of instances across dozens of accounts. Option B (incorrect) involves significant development and maintenance overhead for custom scripting, which is less efficient and robust than using a managed service like CloudFormation StackSets. Option D (incorrect) uses AWS Config rules, which are detective controls. They detect non-compliance *after* it occurs and then trigger remediation, which is not a proactive deployment strategy for rolling out updates, but rather a way to enforce desired state after changes.', 59, 'm_59_2', 18, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 18
WHERE id = 'mock_54_all_1775000123948';

