INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A security engineer discovers an Amazon GuardDuty finding indicating an EC2 instance is communicating with a known command and control (C2) server. The incident response plan requires immediate isolation of the instance for forensic analysis while preserving evidence. Which approach ensures the LEAST data loss for forensic analysis?', '["Modify the EC2 instance''s security groups to deny all inbound and outbound traffic, then create an Amazon EBS snapshot of its attached volumes.","Terminate the compromised EC2 instance immediately to stop the malicious activity, then analyze the CloudTrail logs for forensic details.","Detach the Amazon EBS volumes from the compromised EC2 instance and attach them to a new, isolated forensic instance for analysis.","Stop the EC2 instance to preserve its state, then take an Amazon EBS snapshot and analyze the instance''s memory using AWS Systems Manager."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best approach. Modifying security groups to deny all traffic isolates the instance from the network, preventing further malicious activity while keeping the instance running for memory acquisition and allowing EBS snapshots to be taken without destroying volatile memory. Creating an EBS snapshot preserves the disk state for forensic analysis. Option B (incorrect) represents anti-pattern ap-1.1-001. Terminating the instance immediately destroys volatile memory and other forensic evidence that could be crucial for understanding the attack. Option C (incorrect) detaching EBS volumes from a running instance can cause data corruption and does not preserve the instance''s volatile memory. Option D (incorrect) stopping the instance will clear its volatile memory, which is critical for forensic analysis of running processes and network connections. While it preserves the disk, it loses valuable runtime evidence.', 54, 'm_54_1', 1, NULL, NULL),
  ('mock_54_all_1775003381569', 'A large enterprise needs to automate the response to critical Amazon GuardDuty findings, specifically for EC2 instances exhibiting unusual network activity. The solution must automatically isolate the affected instance and notify the security team. Which combination of services provides the LEAST operational overhead for this automation?', '["Configure Amazon CloudWatch Alarms to monitor GuardDuty findings and trigger an AWS Lambda function to modify security groups.","Deploy AWS Systems Manager Automation documents to periodically check GuardDuty findings and apply isolation actions.","Create an Amazon EventBridge rule to capture GuardDuty findings and trigger an AWS Lambda function to modify the EC2 instance''s security groups and send an Amazon SNS notification.","Set up a custom application on an EC2 instance to continuously poll GuardDuty for new findings and execute isolation scripts."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the least operational overhead. Amazon EventBridge can directly receive GuardDuty findings as events. An EventBridge rule can then trigger an AWS Lambda function, which can execute the necessary API calls to modify security groups for isolation and send an Amazon SNS notification, all without managing servers or complex polling logic. Option A (incorrect) CloudWatch Alarms can monitor metrics, but directly capturing GuardDuty findings is more efficiently done with EventBridge, which is purpose-built for event-driven architectures. Option B (incorrect) while AWS Systems Manager Automation can perform these actions, setting up periodic checks adds more overhead than an event-driven approach, and EventBridge is more direct for reacting to GuardDuty findings. Option D (incorrect) running a custom application on an EC2 instance to poll GuardDuty introduces significant operational overhead, including server management, patching, and ensuring high availability of the polling application itself.', 54, 'm_54_1', 2, NULL, NULL),
  ('mock_54_all_1775003381569', 'A financial institution wants to ensure that all critical security incidents detected by Amazon GuardDuty are automatically routed to a centralized incident management system for tracking and response. The solution should also allow for custom remediation actions based on finding severity. Which service combination is MOST efficient for this requirement?', '["Use Amazon EventBridge to send GuardDuty findings to an Amazon SQS queue, then process with an EC2 instance running custom scripts.","Configure Amazon SNS to subscribe to GuardDuty findings and send notifications to an email distribution list for manual triage.","Forward GuardDuty findings to Amazon Security Hub, then use Security Hub''s custom actions to trigger AWS Lambda functions for remediation.","Integrate Amazon GuardDuty directly with AWS Systems Manager Incident Manager, leveraging EventBridge for automated routing and custom runbooks for remediation."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most efficient. AWS Systems Manager Incident Manager is designed for incident response, allowing for centralized management, automated routing, and the execution of pre-defined runbooks (which can include custom Lambda functions) for remediation. Integrating GuardDuty via EventBridge directly into Incident Manager streamlines the process. Option A (incorrect) using an SQS queue and an EC2 instance for processing adds significant operational overhead for managing the EC2 instance and the custom scripts. Option B (incorrect) Amazon SNS for email notifications is a basic alerting mechanism but lacks the automation, tracking, and structured response capabilities required for a centralized incident management system and custom remediation. Option C (incorrect) while Security Hub can aggregate findings and trigger Lambda, AWS Systems Manager Incident Manager provides a more comprehensive framework for managing the entire incident lifecycle, including escalation, communication, and runbook execution, which is more aligned with a ''centralized incident management system'' requirement.', 54, 'm_54_1', 3, NULL, NULL),
  ('mock_54_all_1775003381569', 'Following a suspected compromise of an EC2 instance, a security analyst needs to collect forensic evidence, including disk contents and volatile memory, without altering the running system more than necessary. Which sequence of actions should the analyst perform to PRESERVE forensic evidence effectively?', '["Isolate the EC2 instance by modifying its security group to deny all traffic, then create an Amazon EBS snapshot of all attached volumes, and finally capture a memory dump.","Immediately stop the EC2 instance to prevent further compromise, then create an Amazon EBS snapshot, and analyze the snapshot offline.","Detach the Amazon EBS volumes from the EC2 instance, attach them to a new forensic instance, and then attempt to capture memory from the original instance.","Terminate the EC2 instance to contain the threat, then rely on AWS CloudTrail logs and VPC Flow Logs for post-mortem analysis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the correct sequence. Isolating the instance first (by modifying security groups) contains the threat without altering its runtime state. Creating an EBS snapshot preserves the disk contents. Capturing a memory dump (e.g., using AWS Systems Manager) preserves volatile data. This approach minimizes alteration of the running system and preserves all types of evidence. Option B (incorrect) stopping the instance clears its volatile memory, losing critical forensic data. Option C (incorrect) detaching volumes from a running instance can corrupt data and is not a standard forensic practice. Capturing memory from a detached instance is not feasible. Option D (incorrect) represents anti-pattern ap-1.1-001. Terminating the instance destroys all volatile memory and the running state, making in-depth forensic analysis impossible.', 54, 'm_54_1', 4, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_54_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A company needs a centralized view of security findings from various AWS services like Amazon GuardDuty, Amazon Macie, and AWS Config across multiple accounts. They also require automated checks against security best practices and compliance standards. Which service combination provides the MOST comprehensive and centralized security posture management?', '["Enable Amazon GuardDuty and Amazon Macie in all accounts, then use AWS CloudWatch to aggregate findings.","Utilize AWS Config to monitor resource compliance and use Amazon SNS for alerts on non-compliant resources.","Enable Amazon Security Hub, integrate it with Amazon GuardDuty, Amazon Macie, and AWS Config, and enable AWS Foundational Security Best Practices standard.","Deploy a custom SIEM solution on EC2 instances to ingest findings from all services and perform compliance checks."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most comprehensive and centralized security posture management. Amazon Security Hub is specifically designed to aggregate, normalize, and prioritize security findings from various AWS services and third-party products. It also provides automated checks against security standards like the AWS Foundational Security Best Practices. Option A (incorrect) while GuardDuty and Macie are essential, CloudWatch is primarily for monitoring metrics and logs, not for aggregating and normalizing diverse security findings into a unified view. This approach would require significant custom effort. Option B (incorrect) AWS Config is excellent for compliance monitoring, but it doesn''t aggregate findings from other services like GuardDuty or Macie, nor does SNS provide a centralized dashboard for managing findings. Option D (incorrect) deploying a custom SIEM on EC2 instances would introduce significant operational overhead for deployment, maintenance, and integration, and it would duplicate much of the functionality already provided by Security Hub, which violates the principle of using managed services for efficiency. This also represents anti-pattern ap-1.2-001 by not leveraging Security Hub for a complete threat picture.', 54, 'm_54_2', 5, NULL, NULL),
  ('mock_54_all_1775003381569', 'A data analytics firm stores vast amounts of customer data in Amazon S3 buckets. They need to continuously monitor these buckets for the presence of personally identifiable information (PII) and other sensitive data, and receive alerts if such data is discovered in unencrypted or publicly accessible locations. Which AWS service is MOST effective for sensitive data discovery and protection in S3?', '["AWS Config rules to check for S3 bucket encryption and public access settings.","Amazon GuardDuty to detect unusual access patterns to S3 buckets containing sensitive data.","AWS CloudTrail logs analyzed by Amazon Athena to identify API calls related to sensitive data access.","Amazon Macie to discover, classify, and protect sensitive data in Amazon S3, with findings integrated into Amazon Security Hub."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective. Amazon Macie is a fully managed data security and data privacy service that uses machine learning and pattern matching to discover, classify, and protect sensitive data in Amazon S3. It can identify PII, financial data, and other sensitive information, and generate findings for unencrypted or publicly accessible sensitive data, which can then be aggregated in Security Hub. Option A (incorrect) AWS Config rules can check for encryption and public access settings but cannot identify the *content* of the data within the objects for PII or other sensitive information. Option B (incorrect) Amazon GuardDuty detects unusual and potentially unauthorized activity, but it does not perform deep content inspection of S3 objects to identify sensitive data types. Option C (incorrect) analyzing CloudTrail logs with Athena can help identify *who* accessed *what* S3 objects, but it does not classify the *content* of those objects for sensitive information.', 54, 'm_54_2', 6, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team wants to detect unusual or anomalous API call patterns in their AWS accounts, such as a user making API calls from an unusual geographic location or attempting to access resources they don''t normally interact with. Which AWS service is MOST effective for detecting unusual API activity?', '["AWS CloudTrail Insights, configured to analyze CloudTrail management events for unusual activity.","Amazon GuardDuty, enabled to monitor for suspicious API calls and potential credential compromise.","AWS Config rules, set up to detect changes in IAM user permissions that could indicate compromise.","Amazon Security Hub, configured to aggregate findings from various services for a holistic view."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective. AWS CloudTrail Insights automatically detects unusual activity in your AWS accounts by continuously analyzing CloudTrail management events. It specifically looks for anomalous patterns in API calls, such as spikes in resource provisioning, unusual locations, or infrequent API calls, which directly addresses the requirement. Option B (incorrect) Amazon GuardDuty detects a wide range of threats, including suspicious API calls and credential compromise, but CloudTrail Insights is specifically designed for behavioral anomaly detection within API activity patterns. Option C (incorrect) AWS Config rules detect configuration changes and compliance violations, not anomalous API call patterns. Option D (incorrect) Amazon Security Hub aggregates findings from multiple services, but it relies on other services like CloudTrail Insights or GuardDuty to generate the initial findings for unusual API activity; it doesn''t detect the anomalies itself.', 54, 'm_54_2', 7, NULL, NULL),
  ('mock_54_all_1775003381569', 'An organization needs to continuously monitor its AWS resource configurations for compliance with internal security policies and industry standards (e.g., CIS Benchmarks). They require alerts for any unauthorized changes to critical resources like security groups or S3 bucket policies. Which AWS service combination is MOST effective for continuous configuration compliance monitoring?', '["Configure Amazon CloudWatch Alarms to monitor changes in resource configurations through AWS CloudTrail logs.","Implement AWS Config rules to evaluate resource configurations against desired settings and integrate findings with Amazon Security Hub.","Use Amazon GuardDuty to detect suspicious activity related to configuration changes and send alerts via Amazon SNS.","Develop custom scripts on an EC2 instance to periodically audit resource configurations and report deviations."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective. AWS Config continuously monitors and records your AWS resource configurations, evaluating them against desired configurations using predefined or custom rules. It can detect unauthorized changes to critical resources and generate findings. Integrating these findings with Amazon Security Hub provides a centralized view and allows for checks against standards like CIS Benchmarks. Option A (incorrect) while CloudWatch Alarms can be set on CloudTrail logs, creating and maintaining alarms for every possible configuration change across numerous resources is complex and less efficient than AWS Config''s managed rules. Option C (incorrect) Amazon GuardDuty is a threat detection service that focuses on malicious activity and unusual behavior, not continuous configuration compliance monitoring against specific rules. Option D (incorrect) developing custom scripts on an EC2 instance introduces significant operational overhead for development, maintenance, and ensuring the reliability and scalability of the auditing solution, which is less efficient than using a managed service like AWS Config.', 54, 'm_54_2', 8, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security operations center (SOC) needs to aggregate and normalize security findings from Amazon GuardDuty, AWS Config, and Amazon Inspector into a single dashboard. They also want to prioritize these findings based on severity and compliance standards. Which AWS service is MOST efficient for aggregating, normalizing, and prioritizing security findings?', '["Amazon CloudWatch Dashboards to display metrics and logs from each service.","AWS CloudTrail Insights to detect anomalies across all service logs and centralize them.","Amazon SQS queues to collect findings from each service for a custom processing application.","Amazon Security Hub, with enabled integrations for GuardDuty, Config, and Inspector, and a configured compliance standard."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most efficient. Amazon Security Hub is specifically designed to aggregate, normalize, and prioritize security findings from various AWS services (like GuardDuty, Config, and Inspector) and third-party solutions into a single, comprehensive view. It also allows for checks against compliance standards and provides a consolidated dashboard. Option A (incorrect) CloudWatch Dashboards can display metrics and logs, but they don''t normalize findings into a common format (ASFF) or provide built-in prioritization based on security standards. Option B (incorrect) CloudTrail Insights focuses on detecting unusual API activity, not on aggregating and normalizing security findings from various services. Option C (incorrect) using SQS queues for a custom processing application would introduce significant operational overhead for developing, deploying, and maintaining the application to perform aggregation, normalization, and prioritization, which Security Hub provides as a managed service. This also represents anti-pattern ap-1.2-001 by not leveraging Security Hub for a complete threat picture.', 54, 'm_54_2', 9, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_54_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A security team identifies a compromised EC2 instance. Their incident response playbook dictates isolating the instance from the network, creating a forensic copy of its disks, and then analyzing the copy. Which approach MINIMIZES impact on the compromised instance while preserving evidence?', '["Modify the EC2 instance''s security groups to block all inbound and outbound network traffic, then take Amazon EBS snapshots of all attached volumes.","Immediately stop the EC2 instance to prevent further malicious activity, then detach its Amazon EBS volumes for analysis.","Terminate the EC2 instance to contain the threat, then rely on AWS CloudTrail logs for forensic investigation.","Detach the EC2 instance''s network interface, then create a new EC2 instance from its AMI for analysis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best approach. Modifying security groups isolates the instance from the network without altering its runtime state, which is crucial for preserving volatile memory and active processes for potential memory acquisition. Taking EBS snapshots creates a point-in-time copy of the disk for forensic analysis. Option B (incorrect) stopping the EC2 instance will clear its volatile memory, which contains valuable forensic evidence. Option C (incorrect) represents anti-pattern ap-1.1-001. Terminating the instance destroys the instance, including its volatile memory and any running processes, making detailed forensic analysis impossible. CloudTrail logs provide API activity, not instance-level forensic data. Option D (incorrect) detaching the network interface isolates the instance but creating a new instance from its AMI would not capture the current state of the compromised instance or its disks, only the base image.', 54, 'm_54_3', 10, NULL, NULL),
  ('mock_54_all_1775003381569', 'An organization wants to automate the response to critical Amazon GuardDuty findings that indicate a potential compromise of an EC2 instance. The automation should isolate the instance and trigger a notification to the incident response team. Which solution requires the LEAST manual intervention for initial incident response?', '["Configure Amazon SNS to send GuardDuty findings to an email alias, and then manually apply security group changes.","Create an Amazon EventBridge rule to capture GuardDuty findings, trigger an AWS Lambda function to modify the EC2 instance''s security groups, and send an Amazon SNS notification.","Implement AWS Systems Manager Automation documents that are manually invoked by the incident response team upon receiving a GuardDuty alert.","Set up Amazon CloudWatch Alarms on GuardDuty metrics to trigger an AWS Auto Scaling group to replace the compromised instance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) requires the least manual intervention. Amazon EventBridge can directly receive GuardDuty findings. An EventBridge rule can then automatically trigger an AWS Lambda function to programmatically modify the EC2 instance''s security groups for isolation and send an Amazon SNS notification to the incident response team. This creates a fully automated initial response. Option A (incorrect) requires manual intervention to apply security group changes, which is not ideal for rapid response. Option C (incorrect) while AWS Systems Manager Automation documents are powerful, if they require manual invocation, they do not meet the ''least manual intervention'' requirement for initial response. Option D (incorrect) replacing the instance with Auto Scaling might be part of a recovery plan, but it destroys the compromised instance immediately without preserving forensic evidence, which is an anti-pattern (ap-1.1-001).', 54, 'm_54_3', 11, NULL, NULL),
  ('mock_54_all_1775003381569', 'After an IAM user''s credentials are confirmed compromised, the security team needs to ensure that any existing active sessions using those credentials are immediately terminated, in addition to rotating the access keys. Which AWS action IMMEDIATELY invalidates all active sessions?', '["Delete the compromised IAM user''s access keys and then create new ones, which forces re-authentication.","Use the `aws iam revoke-session` command or API call for the compromised IAM user, after rotating the access keys.","Apply an explicit deny policy to the IAM user''s permissions, preventing any further actions.","Change the IAM user''s password, which automatically invalidates all active console and programmatic sessions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most immediate way to invalidate all active sessions. Applying an explicit deny policy to the IAM user''s permissions, particularly one that denies `sts:AssumeRole` or `*` actions, will cause any active sessions (including those created via AWS STS) to fail authorization checks immediately. While `revoke-session` is also effective, a broad explicit deny policy ensures that any attempt to use existing credentials or sessions is blocked at the authorization level. Option A (incorrect) deleting and recreating keys does not guarantee immediate termination of active sessions, especially STS sessions. Option B (incorrect) while `revoke-session` is effective, the question asks for the action that *immediately* invalidates all active sessions, and an explicit deny policy directly impacts authorization for all requests. `revoke-session` is a specific API call that can be made, but a policy change is a fundamental authorization control. This option also represents anti-pattern ap-1.1-002 if only key rotation is performed without session invalidation. Option D (incorrect) changing the password primarily affects console access and future programmatic access but does not necessarily invalidate all existing active programmatic sessions or STS sessions.', 54, 'm_54_3', 12, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security engineer needs to create an automated playbook to respond to Amazon GuardDuty findings indicating a potential S3 bucket compromise (e.g., public exposure of sensitive data). The playbook should automatically revert the bucket policy and alert the security team. Which service combination offers the MOST efficient automated remediation for S3 policy changes?', '["An Amazon EventBridge rule that triggers an AWS Lambda function to modify the S3 bucket policy and send an Amazon SNS notification.","An AWS Config rule that detects non-compliant S3 bucket policies and automatically remediates them using a custom action.","An Amazon GuardDuty custom action that directly invokes an AWS Systems Manager Automation document to revert the S3 policy.","A custom application running on an EC2 instance that continuously polls GuardDuty for S3 findings and executes policy changes."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most efficient automated remediation. Amazon EventBridge can directly receive GuardDuty findings. An EventBridge rule can then trigger an AWS Lambda function, which can execute the necessary AWS SDK calls to modify the S3 bucket policy (e.g., make it private) and send an Amazon SNS notification to the security team. This is a serverless, event-driven, and highly efficient approach. Option B (incorrect) while AWS Config rules can detect non-compliant S3 policies and can have remediation actions, GuardDuty findings are typically a more immediate indicator of a *compromise* or *threat* rather than just a compliance deviation. The EventBridge-Lambda pattern is more direct for real-time threat response. Option C (incorrect) GuardDuty does not have ''custom actions'' that directly invoke Systems Manager Automation documents. GuardDuty findings are typically routed via EventBridge. Option D (incorrect) a custom application on an EC2 instance introduces significant operational overhead for server management, patching, and ensuring the high availability of the polling application itself, which is less efficient than a serverless approach.', 54, 'm_54_3', 13, NULL, NULL);

