INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A large enterprise needs to inspect all east-west traffic between different application subnets within its VPC for threats and prevent data exfiltration to unauthorized external domains. The security team requires a solution that offers stateful inspection and intrusion prevention, with centralized management across the VPC. Which approach BEST meets these requirements?', '["Deploy AWS Network Firewall in a centralized inspection VPC and route all inter-subnet traffic through it, managing rules via AWS Firewall Manager.","Configure security groups and network ACLs extensively between all subnets and use VPC Flow Logs for monitoring.","Implement Amazon GuardDuty to detect anomalies in VPC Flow Logs and trigger AWS Lambda functions for automated blocking.","Use third-party firewall appliances on EC2 instances in each subnet to inspect traffic and apply custom rules."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages AWS Network Firewall for stateful inspection, intrusion prevention, and web filtering, which is ideal for east-west traffic inspection and preventing data exfiltration. Integrating it with AWS Firewall Manager allows for centralized policy management across the VPC, meeting the requirements for advanced threat protection and centralized control. Option B (incorrect) relies solely on security groups and network ACLs, which provide stateless and stateful packet filtering but lack advanced threat inspection capabilities like intrusion prevention or deep packet inspection. This approach would also be complex to manage at scale. Option C (incorrect) provides threat detection but not active inline prevention or filtering of traffic, which is required for inspection and prevention. It''s a reactive solution rather than a proactive inline one. Option D (incorrect) introduces significant operational overhead for deploying, managing, and scaling third-party appliances, which goes against the goal of efficient centralized management and native AWS services.', 56, 'm_56_2', 1, NULL, NULL),
  ('mock_54_all_1775003381569', 'A financial institution requires strict inbound and outbound filtering for its application subnets, including stateful inspection and intrusion prevention. The security team wants to minimize manual rule management and ensure that all traffic passing through the firewall is logged for compliance purposes. Which solution provides the LEAST operational overhead for advanced filtering?', '["Deploy a third-party firewall appliance on an EC2 instance in each application subnet and manually configure its rules and logging.","Implement AWS Network Firewall in a centralized inspection VPC, routing all relevant traffic through it, and configure logging to Amazon S3 and Amazon CloudWatch Logs.","Use a combination of security groups and network ACLs to control traffic flow and enable VPC Flow Logs for visibility.","Configure Amazon GuardDuty to detect suspicious network activity and automatically update security group rules."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS Network Firewall, a managed service that provides stateful inspection, intrusion prevention, and web filtering with minimal operational overhead compared to self-managed solutions. It integrates natively with VPC routing and offers built-in logging capabilities to Amazon S3 and Amazon CloudWatch Logs for compliance. Option A (incorrect) involves deploying and managing third-party firewall appliances on EC2 instances, which significantly increases operational overhead for patching, scaling, and rule management. Option C (incorrect) offers basic packet filtering but lacks the advanced stateful inspection and intrusion prevention capabilities required. While VPC Flow Logs provide visibility, they don''t offer inline prevention. Option D (incorrect) is a detection service that can trigger actions, but it does not provide the inline, stateful inspection and intrusion prevention capabilities of a firewall, nor does it inherently minimize manual rule management for advanced filtering.', 56, 'm_56_2', 2, NULL, NULL),
  ('mock_54_all_1775003381569', 'An organization needs to isolate its production databases from application servers within the same VPC, allowing only specific ports and protocols for communication. Additionally, network ACLs must be configured to prevent any accidental overly permissive rules. Which combination of controls provides the MOST granular network isolation?', '["Use AWS Network Firewall to inspect traffic between subnets and apply granular rules.","Implement a single, restrictive network ACL for the entire VPC and apply broad security group rules to instances.","Apply specific security group rules to allow only necessary inbound/outbound traffic for database and application instances, and use network ACLs on subnets as a stateless, coarse-grained defense.","Deploy Amazon GuardDuty to monitor for unauthorized communication attempts between instances and databases."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most granular network isolation by combining security groups and network ACLs. Security groups are stateful and operate at the instance level, allowing precise control over traffic to and from instances. Network ACLs are stateless and operate at the subnet level, providing a coarse-grained, second layer of defense that can prevent accidental overly permissive security group rules from exposing resources. Option A (incorrect) would provide advanced inspection but is typically used for broader traffic inspection and routing, not necessarily for granular instance-level isolation within a subnet or between tightly coupled subnets where security groups are more efficient. Option B (incorrect) suggests a single, restrictive network ACL and broad security groups, which would be difficult to manage and could lead to connectivity issues or insufficient granularity. Option D (incorrect) is a threat detection service, not a network isolation or enforcement mechanism.', 56, 'm_56_2', 3, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company wants to restrict access to Amazon S3 from EC2 instances in a private subnet to only specific S3 buckets, without routing traffic through a NAT Gateway or exposing the S3 traffic to the public internet. The solution must also ensure that only authorized IAM roles can access these buckets. Which approach is MOST secure and cost-effective for data access?', '["Configure a NAT Gateway in the public subnet and use S3 bucket policies to restrict access.","Route all S3 traffic through a VPN connection to an on-premises network, then back to AWS.","Create a Gateway VPC Endpoint for Amazon S3 in the VPC and attach a VPC endpoint policy that restricts access to specific S3 buckets and IAM roles.","Use an Interface VPC Endpoint for S3 and configure security groups on the endpoint to allow traffic from specific EC2 instances."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most secure and cost-effective approach. A Gateway VPC Endpoint for Amazon S3 allows EC2 instances in private subnets to access S3 directly without traversing the internet or requiring a NAT Gateway, thus reducing costs and increasing security. Attaching a VPC endpoint policy, in conjunction with S3 bucket policies, provides granular control over which specific S3 buckets and IAM roles can be accessed, ensuring least privilege. Option A (incorrect) would route S3 traffic through a NAT Gateway, incurring data processing costs and exposing traffic to the public internet, which is less secure and less cost-effective. Option B (incorrect) would introduce significant latency, complexity, and cost by routing traffic through an on-premises network. Option D (incorrect) suggests an Interface VPC Endpoint for S3, which is generally used for API access to S3, not for direct data transfer to S3 buckets, and would incur higher costs than a Gateway Endpoint for S3.', 56, 'm_56_2', 4, NULL, NULL),
  ('mock_54_all_1775003381569', 'A large enterprise with multiple VPCs across several AWS accounts needs to centralize network security policies for security groups and AWS Network Firewall rules. The security team wants to ensure consistent application of these policies across all accounts and VPCs, minimizing manual configuration and auditing efforts. Which service should be used to achieve the MOST efficient centralized security management?', '["AWS Firewall Manager.","AWS Organizations with Service Control Policies (SCPs).","AWS Systems Manager State Manager.","Manually apply security group and AWS Network Firewall rules in each account using CloudFormation templates."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Firewall Manager, which is specifically designed to centrally configure and manage firewall rules across multiple accounts and VPCs within an AWS Organization. It allows security administrators to define a common set of security group rules, AWS WAF rules, and AWS Network Firewall policies, and then automatically apply them to resources across the organization, ensuring consistency and reducing operational overhead. Option B (incorrect) AWS Organizations with Service Control Policies (SCPs) can restrict actions that accounts can perform, but they do not directly manage or deploy security group or AWS Network Firewall rules. Option C (incorrect) AWS Systems Manager State Manager can manage configurations on EC2 instances but is not designed for centralized network security policy deployment across VPCs and accounts for services like AWS Network Firewall. Option D (incorrect) would involve significant manual effort and is prone to inconsistencies, failing to meet the requirement for efficient centralized management.', 56, 'm_56_2', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_56_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A company runs critical EC2 instances and needs to ensure they are regularly scanned for software vulnerabilities and unintended network exposure, with automated reporting to the security team. The solution should integrate seamlessly with existing AWS services and require LEAST manual effort for continuous vulnerability management. Which combination of services should be used?', '["Manually install and configure a third-party vulnerability scanner on each EC2 instance and set up custom reporting.","Enable Amazon Inspector for EC2 instances to perform continuous vulnerability scanning and network reachability analysis, integrating findings with AWS Security Hub.","Use AWS Systems Manager Patch Manager to keep instances updated and rely on AWS Config rules to check for security group misconfigurations.","Implement Amazon GuardDuty for threat detection and use AWS Lambda to trigger custom vulnerability scans."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon Inspector, a managed vulnerability management service that automatically discovers and scans EC2 instances for software vulnerabilities and unintended network exposure. It provides continuous scanning and integrates findings with AWS Security Hub for centralized reporting, requiring minimal manual effort. Option A (incorrect) involves significant manual effort for installation, configuration, and reporting of a third-party scanner, which goes against the ''least manual effort'' constraint. Option C (incorrect) focuses on patching and configuration compliance but does not provide comprehensive software vulnerability scanning or network reachability analysis like Amazon Inspector. Option D (incorrect) is a threat detection service, not a vulnerability scanner. While it can detect threats, it doesn''t proactively identify software vulnerabilities or unintended network exposure, and custom Lambda functions would increase operational overhead.', 56, 'm_56_3', 6, NULL, NULL),
  ('mock_54_all_1775003381569', 'A development team needs to securely access EC2 instances in private subnets for troubleshooting and maintenance without opening SSH ports to the internet or managing bastion hosts. The solution must ensure that access is granted based on IAM roles and is fully auditable. Which approach provides the MOST secure and operationally efficient access?', '["Configure a bastion host in a public subnet with a highly restricted security group and SSH key management.","Establish a VPN connection to the VPC and then SSH into the instances using private IP addresses.","Utilize AWS Systems Manager Session Manager to establish secure, auditable shell access to instances without opening inbound ports.","Implement a custom solution using AWS Lambda and Amazon API Gateway to proxy SSH connections to private instances."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages AWS Systems Manager Session Manager, which provides secure and auditable shell access to EC2 instances without requiring open inbound ports (like SSH 22) or managing bastion hosts. It integrates with IAM for access control and logs all session activity to Amazon S3 or Amazon CloudWatch Logs for auditing, making it the most secure and operationally efficient solution. Option A (incorrect) requires managing a bastion host, including its security, patching, and SSH keys, which adds operational overhead and still presents a potential attack vector. Option B (incorrect) requires setting up and maintaining a VPN connection, which adds complexity and may not be as granularly controlled or auditable as Session Manager. Option D (incorrect) would be a complex custom solution to build and maintain, increasing operational overhead significantly compared to a native AWS service.', 56, 'm_56_3', 7, NULL, NULL),
  ('mock_54_all_1775003381569', 'An application deployed on EC2 instances requires access to sensitive credentials. The security team wants to prevent Server-Side Request Forgery (SSRF) attacks where a compromised application could query the instance metadata service to retrieve IAM role credentials. Which configuration provides the MOST robust protection against credential theft via SSRF?', '["Implement strong input validation and sanitization within the application code to prevent SSRF vulnerabilities.","Configure security groups to restrict outbound access from the EC2 instance to only necessary endpoints, including blocking access to the instance metadata service IP.","Ensure all EC2 instances are configured to use Instance Metadata Service Version 2 (IMDSv2), which requires a session token for all requests.","Regularly rotate IAM role credentials associated with the EC2 instances using AWS Secrets Manager."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) ensures that all EC2 instances are configured to use Instance Metadata Service Version 2 (IMDSv2). IMDSv2 requires a session token obtained via a PUT request before any GET requests can be made to retrieve metadata, including IAM role credentials. This mechanism effectively blocks most SSRF-based credential theft attacks because the PUT request cannot typically be initiated by a compromised application through an SSRF vulnerability. Option A (incorrect) is a good practice for application security but relies on developers to implement it perfectly, which can be error-prone and doesn''t provide infrastructure-level protection. Option B (incorrect) is generally not feasible or recommended to block access to the instance metadata service IP (169.254.169.254) from the instance itself, as it''s essential for instance operation. Option D (incorrect) is a good security practice for credentials but does not directly prevent an SSRF attack from retrieving *current* credentials if IMDSv1 is in use.', 56, 'm_56_3', 8, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company deploys containerized applications using Amazon ECR and Amazon ECS. They need to automatically identify software vulnerabilities in their container images before deployment to production environments. The solution must be integrated into the CI/CD pipeline and provide actionable insights. Which service should be used for the MOST proactive vulnerability detection for containers?', '["Enable Amazon ECR image scanning to automatically scan new and existing container images for operating system and programming language package vulnerabilities.","Implement Amazon Inspector to scan the running ECS tasks for vulnerabilities and compliance deviations.","Use AWS Systems Manager Patch Manager to ensure the underlying EC2 instances running ECS tasks are patched.","Manually scan container images using a third-party tool before pushing them to Amazon ECR."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes Amazon ECR image scanning, which is a built-in feature that automatically scans container images for operating system and programming language package vulnerabilities. This provides proactive vulnerability detection directly within the container registry, making it ideal for integration into CI/CD pipelines before deployment. Option B (incorrect) Amazon Inspector can scan running ECS tasks, but this is a post-deployment check. The requirement is for detection *before* deployment to production, making ECR image scanning more proactive. Option C (incorrect) AWS Systems Manager Patch Manager ensures the host operating system is patched, but it does not scan the container images themselves for vulnerabilities within their layers. Option D (incorrect) involves manual effort and a third-party tool, which increases operational overhead and may not integrate as seamlessly as a native AWS service.', 56, 'm_56_3', 9, NULL, NULL),
  ('mock_54_all_1775003381569', 'A serverless application uses AWS Lambda functions to process sensitive customer data. The security team needs to ensure that Lambda functions can only access specific resources (e.g., a particular Amazon DynamoDB table) and are isolated within a Virtual Private Cloud (VPC) to prevent unauthorized network access. Which combination of configurations provides the MOST secure isolation and least privilege for Lambda?', '["Configure Lambda functions to run outside a VPC and rely solely on resource-based policies for access control.","Attach an IAM execution role with least privilege permissions to the Lambda function and configure the Lambda function to operate within a VPC.","Use AWS WAF to protect the Amazon API Gateway endpoint that triggers the Lambda function.","Encrypt sensitive data within the Lambda function code before storing it in external services."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most secure isolation and least privilege. Attaching an IAM execution role with least privilege permissions ensures that the Lambda function can only access the specific AWS resources it needs (e.g., a DynamoDB table). Configuring the Lambda function to operate within a VPC provides network isolation, allowing it to access private resources within the VPC and preventing unauthorized network access to or from the internet, unless explicitly configured. Option A (incorrect) running Lambda outside a VPC does not provide network isolation, and while resource-based policies are important, they are not sufficient for network-level isolation. Option C (incorrect) protects the API Gateway endpoint, but not the Lambda function''s internal network access or its permissions to other AWS services. Option D (incorrect) is a good practice for data protection but does not address the network isolation or least privilege access control for the Lambda function itself.', 56, 'm_56_3', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_56_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'An e-commerce website hosted on Amazon CloudFront and an Application Load Balancer (ALB) experiences frequent web application attacks (OWASP Top 10) and occasional volumetric DDoS attempts at Layer 7. The security team needs a solution that can block these attacks effectively while minimizing impact on legitimate users. Which approach provides the MOST effective protection against web application attacks and application-layer DDoS?', '["Enable AWS Shield Standard on the ALB and rely on its automatic protections.","Implement security groups on the ALB to restrict traffic based on IP addresses.","Deploy AWS WAF with managed rule groups for OWASP Top 10 and custom rules for rate-based limiting, associating it with both CloudFront and the ALB.","Use Amazon GuardDuty to detect web application attacks and trigger AWS Lambda functions to update security group rules."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution. AWS WAF is designed to protect web applications from common web exploits (like the OWASP Top 10) and application-layer DDoS attacks. By deploying AWS WAF with managed rule groups and custom rate-based rules, and associating it with both CloudFront (for edge protection) and the ALB (for origin protection), the website gains comprehensive protection against the specified threats. Option A (incorrect) AWS Shield Standard provides automatic protection against common Layer 3/4 DDoS attacks but does not offer specific protection against web application exploits or sophisticated Layer 7 DDoS attacks. Option B (incorrect) using security groups on the ALB is too coarse-grained and not effective against sophisticated web application attacks or dynamic Layer 7 DDoS, as IP addresses can change rapidly. Option D (incorrect) Amazon GuardDuty is a threat detection service, not a prevention service. While it can detect threats, relying on Lambda to update security groups reactively is less effective than proactive, inline WAF protection.', 56, 'm_56_1', 11, NULL, NULL),
  ('mock_54_all_1775003381569', 'A public-facing web application is experiencing volumetric DDoS attacks at Layer 3/4 and sophisticated application-layer attacks. The company requires 24/7 access to the AWS DDoS Response Team (DRT) and cost protection against scaling charges during attacks. Which solution provides the MOST comprehensive DDoS protection with expert support?', '["Enable AWS Shield Standard on all protected resources and configure AWS WAF with rate-based rules.","Subscribe to AWS Shield Advanced and configure AWS WAF with custom rules and managed rule groups, ensuring it''s associated with relevant resources.","Implement Amazon CloudFront with geo-restriction and origin access control (OAC) to filter traffic.","Deploy a third-party DDoS mitigation service in front of the AWS infrastructure."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most comprehensive solution. AWS Shield Advanced provides enhanced DDoS protection for Layer 3/4 and Layer 7 attacks, including 24/7 access to the AWS DDoS Response Team (DRT) and cost protection against scaling charges from DDoS-related traffic. When combined with AWS WAF, which provides application-layer protection through custom rules and managed rule groups, it offers robust defense against both volumetric and sophisticated application-layer attacks. Option A (incorrect) AWS Shield Standard provides automatic protection against common Layer 3/4 attacks but does not include DRT access or cost protection, nor does it offer advanced Layer 7 mitigation. Option C (incorrect) Amazon CloudFront with geo-restriction and OAC helps with content delivery and basic access control but is not a dedicated DDoS mitigation solution for volumetric or application-layer attacks. Option D (incorrect) deploying a third-party service adds complexity, potential latency, and may not integrate as seamlessly or provide the same level of support as AWS Shield Advanced.', 56, 'm_56_1', 12, NULL, NULL),
  ('mock_54_all_1775003381569', 'A media company delivers sensitive content globally via Amazon CloudFront. They need to restrict access to their content to specific geographic regions (e.g., North America and Europe) and prevent unauthorized websites from embedding or hotlinking their media files. Which combination of services provides the MOST effective content access control and geo-restriction?', '["Configure Amazon CloudFront geo-restriction settings and implement signed URLs or signed cookies for content access, combined with AWS WAF for referrer-based blocking.","Use AWS WAF with IP-based geo-blocking rules and custom rules to block specific user-agent strings.","Implement Amazon S3 bucket policies to restrict access based on source IP addresses and use CloudFront for caching only.","Deploy AWS Shield Advanced to protect CloudFront distributions and rely on its traffic filtering capabilities."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most effective solution. Amazon CloudFront''s geo-restriction feature allows blocking or whitelisting content access based on the user''s country. Combining this with signed URLs or signed cookies ensures that only authorized users or applications can access the content for a limited time. AWS WAF can then be used to create custom rules that inspect the ''Referer'' header to prevent hotlinking from unauthorized websites. Option B (incorrect) using AWS WAF''s IP-based geo-blocking is less efficient than CloudFront''s native geo-restriction, and user-agent string blocking is easily bypassed. Option C (incorrect) Amazon S3 bucket policies are for direct S3 access and do not leverage CloudFront''s edge capabilities for global content delivery and geo-restriction. Option D (incorrect) AWS Shield Advanced is for DDoS protection and does not provide content access control or geo-restriction capabilities.', 56, 'm_56_1', 13, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company wants to enforce a consistent set of AWS WAF rules across all its Amazon CloudFront distributions and Application Load Balancers in multiple AWS accounts within an AWS Organization. The security team needs to manage these rules centrally and ensure automatic deployment to new and existing resources. Which service should be used for the LEAST operational overhead for consistent WAF policy deployment?', '["Manually create and update AWS WAF web ACLs in each AWS account and associate them with resources.","Utilize AWS Firewall Manager to define a centralized WAF policy and automatically apply it across accounts and resources within the AWS Organization.","Develop custom AWS Lambda functions to synchronize WAF rules across accounts and resources.","Use AWS Systems Manager State Manager to deploy WAF rules to EC2 instances running web servers."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Firewall Manager, which is specifically designed for centralized management and automatic deployment of security policies, including AWS WAF rules, across multiple accounts and resources within an AWS Organization. This significantly reduces operational overhead and ensures consistency. Option A (incorrect) involves manual effort in each account, which is prone to errors and high operational overhead, especially in a multi-account environment. Option C (incorrect) developing and maintaining custom Lambda functions for synchronization would introduce significant development and operational overhead, defeating the purpose of minimizing effort. Option D (incorrect) AWS Systems Manager State Manager is used for managing configurations on EC2 instances, not for deploying or managing AWS WAF rules on CloudFront distributions or Application Load Balancers.', 56, 'm_56_1', 14, NULL, NULL),
  ('mock_54_all_1775003381569', 'A public-facing website is experiencing a high volume of requests from a single IP address, impacting legitimate user experience and potentially indicating a brute-force attack. The security team needs to automatically block or rate-limit these abusive requests without blocking all traffic from that IP permanently. Which AWS WAF feature is MOST efficient for automated protection against abusive traffic from specific IPs?', '["AWS WAF custom rules with IP set matching.","AWS WAF managed rule groups for common threats.","AWS WAF rate-based rules configured to count requests from a single IP address over a 5-minute period and block if a threshold is exceeded.","AWS WAF Bot Control managed rule group to identify and block bot traffic."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS WAF rate-based rules. These rules allow you to specify a threshold for the number of requests allowed from a single IP address within a 5-minute sliding window. If the request rate exceeds the threshold, AWS WAF automatically blocks or counts subsequent requests from that IP address, effectively mitigating abusive traffic or brute-force attacks without permanently blocking the IP. Option A (incorrect) AWS WAF custom rules with IP set matching can block specific IPs, but it requires manual identification and updating of the IP set, which is not automated for dynamic abuse. Option B (incorrect) AWS WAF managed rule groups provide protection against common web exploits but are not specifically designed for dynamic rate-limiting of abusive traffic from a single IP. Option D (incorrect) AWS WAF Bot Control is effective against known bots but may not specifically target high-volume requests from a single, potentially legitimate, but abusive IP address.', 56, 'm_56_1', 15, NULL, NULL);

