-- Module: m_56_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'An administrator is troubleshooting a connectivity issue between an EC2 instance in a private subnet and an Amazon RDS database in another private subnet within the same VPC. Both instances have complex security group rules, and network ACLs are also in place. The administrator suspects a network path blockage. Which method is the MOST systematic and accurate to identify the exact network path blockage?', '["Temporarily loosen all security group rules and network ACLs for both instances to see if connectivity is restored.","Review VPC Flow Logs to identify dropped packets and analyze source/destination IP addresses and ports.","Use the AWS CLI to describe all security groups and network ACLs and manually compare rules.","Utilize VPC Reachability Analyzer to perform a path analysis between the EC2 instance and the RDS database, identifying blocking components."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) utilizes VPC Reachability Analyzer, which is specifically designed to systematically analyze and identify network path blockages between two resources in a VPC. It provides a detailed path analysis, highlighting exactly which security group rule, network ACL rule, or route table entry is blocking traffic, making it the most accurate and systematic diagnostic tool. Option A (incorrect) is an anti-pattern (ap-3.3-001) as it creates security vulnerabilities by loosening controls and does not systematically identify the root cause. Option B (incorrect) VPC Flow Logs can show dropped packets, but interpreting them for complex scenarios with multiple rules can be time-consuming and less precise than Reachability Analyzer. Option C (incorrect) manually reviewing rules is tedious, error-prone, and inefficient for complex rule sets.', 56, 'm_56_4', 16, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security engineer suspects that an AWS Network Firewall rule is blocking legitimate traffic between two VPCs connected via a Transit Gateway. They need to quickly identify which specific rule in the firewall policy is causing the issue without impacting production traffic. Which method is MOST efficient to pinpoint the blocking Network Firewall rule?', '["Review the AWS Network Firewall flow logs and alert logs in Amazon CloudWatch Logs to identify dropped packets and the specific rule action.","Temporarily disable the AWS Network Firewall and check if traffic flows, then re-enable it rule by rule.","Use VPC Reachability Analyzer to test connectivity through the Transit Gateway and Network Firewall.","Inspect the route tables in both VPCs and the Transit Gateway to ensure traffic is routed correctly to the Network Firewall."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient method. AWS Network Firewall publishes detailed flow logs and alert logs to Amazon CloudWatch Logs and Amazon S3. These logs contain information about traffic that was allowed, dropped, or alerted on, including the specific rule that caused the action. By analyzing these logs, the engineer can quickly pinpoint the exact rule blocking the legitimate traffic. Option B (incorrect) temporarily disabling the firewall or re-enabling rules one by one would significantly impact production traffic and is not a recommended troubleshooting step. Option C (incorrect) VPC Reachability Analyzer can confirm if a path exists, but it doesn''t provide the granularity to identify a specific blocking rule within the AWS Network Firewall policy. Option D (incorrect) inspecting route tables is a necessary step to ensure traffic is *routed* to the firewall, but it won''t identify a specific blocking *rule* within the firewall itself.', 56, 'm_56_4', 17, NULL, NULL),
  ('mock_54_all_1775003381569', 'A developer reports that their application running on an EC2 instance cannot access an Amazon S3 bucket, despite a Gateway VPC Endpoint for S3 being configured in the VPC. The security team needs to verify if the VPC endpoint policy is too restrictive, preventing access to the required S3 bucket. Which method is the MOST direct to diagnose S3 access issues related to endpoint policies?', '["Review the S3 bucket policy to ensure the EC2 instance''s IAM role has permissions to the bucket.","Examine the VPC endpoint policy attached to the Gateway VPC Endpoint for S3 to ensure it explicitly allows access from the EC2 instance''s IAM role to the target S3 bucket.","Check the security groups and network ACLs associated with the EC2 instance and the VPC endpoint.","Use VPC Flow Logs to see if traffic is reaching the VPC endpoint for S3."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most direct method. When a Gateway VPC Endpoint for S3 is used, both the S3 bucket policy and the VPC endpoint policy must grant access. If the S3 bucket policy is correct, the next logical step is to examine the VPC endpoint policy. This policy controls what principals (IAM roles/users) can access which S3 buckets through that specific endpoint. A restrictive endpoint policy can override permissive S3 bucket policies, causing access denied errors. Option A (incorrect) while important, the question implies the S3 bucket policy might already be correct, focusing on the endpoint policy. Option C (incorrect) security groups and network ACLs are not applicable to Gateway VPC Endpoints for S3 as they operate at the network interface level, and Gateway Endpoints do not have network interfaces. Option D (incorrect) VPC Flow Logs can show traffic flow, but they won''t directly tell you if an access denied error is due to a restrictive VPC endpoint policy.', 56, 'm_56_4', 18, NULL, NULL),
  ('mock_54_all_1775003381569', 'A new application deployed on EC2 instances cannot receive inbound traffic on a specific port, even though the instance''s security group appears to allow it. The network ACLs for the subnet are also in place. The security team needs to determine if a network ACL or security group is blocking the traffic. Which approach is the MOST effective way to determine this?', '["Modify the security group to allow all inbound traffic (0.0.0.0/0) and test connectivity.","Analyze VPC Flow Logs for the network interface of the EC2 instance, looking for ''REJECT'' entries on the specific port, and then cross-reference with security group and network ACL rules.","Temporarily remove all network ACLs from the subnet and test connectivity.","Use `ping` and `traceroute` commands from a source instance to the target EC2 instance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and systematic approach. VPC Flow Logs capture information about IP traffic going to and from network interfaces, including whether traffic was accepted or rejected. By analyzing ''REJECT'' entries for the specific port and destination IP, and then cross-referencing the timestamps with the security group and network ACL rules, the security team can accurately determine which rule is blocking the traffic. Option A (incorrect) is an anti-pattern (ap-3.3-001) as it unnecessarily broadens security access, creating a vulnerability, and doesn''t pinpoint the exact blocking rule. Option C (incorrect) temporarily removing all network ACLs is also a risky action that can expose resources and doesn''t precisely identify the blocking rule. Option D (incorrect) `ping` and `traceroute` can help diagnose basic network reachability but do not provide insight into specific security group or network ACL rejections at the granular level needed.', 56, 'm_56_4', 19, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team wants to ensure that all traffic leaving a specific private subnet and destined for the internet is inspected by AWS Network Firewall. They need to verify that the traffic is correctly routed through the firewall and that the firewall is actively inspecting the traffic. Which combination of actions provides the MOST effective way to validate Network Firewall traffic inspection and routing?', '["Configure a default route in the private subnet''s route table pointing to an Internet Gateway and enable VPC Flow Logs.","Modify the private subnet''s route table to direct internet-bound traffic to the AWS Network Firewall endpoint, then review AWS Network Firewall flow logs and alert logs.","Deploy a NAT Gateway in a public subnet and configure the private subnet''s route table to use the NAT Gateway for internet access.","Use VPC Reachability Analyzer to confirm that the EC2 instances in the private subnet can reach external internet destinations."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach. To ensure all internet-bound traffic from a private subnet is inspected by AWS Network Firewall, the private subnet''s route table must be configured to direct this traffic to the Network Firewall endpoint. Once routed, reviewing the AWS Network Firewall''s flow logs and alert logs (in Amazon CloudWatch Logs or Amazon S3) will confirm that traffic is indeed passing through the firewall and being inspected according to its rules. Option A (incorrect) configuring a default route to an Internet Gateway bypasses the Network Firewall entirely for internet-bound traffic. Option C (incorrect) deploying a NAT Gateway provides internet access but does not route traffic through AWS Network Firewall for inspection unless specifically configured with appropriate routing. Option D (incorrect) VPC Reachability Analyzer can confirm reachability but doesn''t verify that the traffic is *inspected* by the Network Firewall or provide details on firewall rule actions.', 56, 'm_56_4', 20, NULL, NULL);

