INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A global enterprise needs to provide its workforce with single sign-on (SSO) access to multiple AWS accounts within an AWS Organization, integrating with their existing corporate Microsoft Active Directory. The solution must minimize administrative overhead for user management and credential rotation while ensuring secure access.', '["Implement AWS IAM Identity Center and connect it to the corporate Active Directory using AWS Directory Service.","Create individual IAM users for each employee in every AWS account and configure SAML federation manually.","Use Amazon Cognito User Pools to manage workforce identities and integrate it with Active Directory.","Set up a custom federation proxy application on an Amazon EC2 instance to integrate Active Directory with AWS IAM roles."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the recommended approach for managing workforce access to multiple AWS accounts within an AWS Organization. AWS IAM Identity Center (successor to AWS SSO) provides centralized SSO access, integrates directly with AWS Directory Service (which can connect to on-premises Active Directory), and handles temporary credential issuance, significantly minimizing administrative overhead for user management and credential rotation. Option B (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users for human access, which leads to high administrative overhead for managing credentials, permissions, and rotation across multiple accounts. Option C (incorrect) is primarily designed for customer-facing applications and external users, not for internal workforce access, making it unsuitable for this enterprise scenario. Option D (incorrect) would introduce significant operational overhead for development, maintenance, and scaling of a custom solution, which contradicts the requirement to minimize administrative overhead.', 57, 'm_57_1', 1, NULL, NULL),
  ('mock_54_all_1775003381569', 'A development team is troubleshooting an "Access Denied" error when attempting to launch an Amazon EC2 instance, despite their IAM user having an identity-based policy that explicitly allows `ec2:RunInstances`. An AWS Organizations Service Control Policy (SCP) is also in effect, which explicitly denies `ec2:RunInstances` for instances of type `t2.micro`. The team is trying to launch a `t2.micro` instance.', '["The identity-based policy is incorrectly configured and needs to be updated to explicitly allow `t2.micro` instances.","An explicit deny in an AWS Organizations Service Control Policy (SCP) always takes precedence over an allow in an identity-based policy.","The IAM user''s session policy is overriding the identity-based policy, causing the denial.","The resource-based policy on the Amazon EC2 instance itself is denying the launch request."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) accurately describes the IAM policy evaluation logic. An explicit deny in any policy, including an AWS Organizations Service Control Policy (SCP), always overrides any allow statement in other policies, such as identity-based policies. This is a fundamental principle of IAM policy evaluation, directly addressing anti-pattern [ap-4.1-001]. Option A (incorrect) is wrong because even if the identity policy explicitly allowed `t2.micro`, the SCP''s explicit deny would still block the action. Option C (incorrect) is unlikely to be the primary cause unless a session policy was specifically applied, and even then, an SCP''s explicit deny would still win. Option D (incorrect) is not applicable here as EC2 instances do not have resource-based policies that would deny their own launch; the denial is happening at the API call level before the instance is created.', 57, 'm_57_1', 2, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company uses Amazon Cognito User Pools for customer authentication in their mobile application. They need to grant these authenticated users temporary, limited access to upload files directly to a specific Amazon S3 bucket. The solution must ensure that users only have access to their own designated folder within the bucket.', '["Configure an IAM user for each authenticated user and provide them with long-term credentials.","Create a custom API Gateway endpoint that uses AWS Lambda to upload files to Amazon S3 on behalf of the users.","Use Amazon Cognito Identity Pools to exchange authenticated user tokens for temporary AWS credentials via AWS STS.","Attach a resource-based policy directly to the Amazon S3 bucket that allows public write access for all users."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate solution. Amazon Cognito Identity Pools (federated identities) allow you to exchange tokens from authenticated users (via User Pools or other identity providers) for temporary, limited-privilege AWS credentials using AWS STS. These temporary credentials can then be used by the mobile application to directly access AWS services like Amazon S3, with policies configured to restrict access to specific user folders. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users for human access, which is not scalable or secure for customer-facing applications due to the management of long-term credentials. Option B (incorrect) would add unnecessary complexity and latency by routing all S3 uploads through a custom API and Lambda function, increasing operational overhead. Option D (incorrect) is a severe security anti-pattern, granting public write access to an S3 bucket, which would expose the bucket to unauthorized uploads and data breaches.', 57, 'm_57_1', 3, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team wants to ensure that all IAM roles created in their AWS accounts do not grant permissions that are never used. They need a continuous mechanism to identify and report on these unused permissions to enforce the principle of least privilege and reduce the attack surface.', '["Manually review IAM policies and AWS CloudTrail logs periodically to identify unused permissions.","Implement AWS Config rules to flag IAM policies that are overly permissive.","Use the IAM Policy Simulator to test and validate permissions for each role after creation.","Leverage AWS IAM Access Analyzer to continuously monitor and report on unused access for roles and users."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective solution. AWS IAM Access Analyzer provides continuous monitoring to identify unused access, including unused roles, unused access keys, and unused permissions within policies. It helps security teams enforce the principle of least privilege by reporting on permissions that have not been exercised, allowing for their removal. Option A (incorrect) is a manual and reactive approach that is not scalable or continuous, making it prone to human error and delays in identifying unused permissions. Option B (incorrect) can help identify overly permissive policies but doesn''t specifically focus on identifying permissions that are *unused* over time. Option C (incorrect) is a valuable tool for testing policy effects during creation or modification but does not provide continuous monitoring of *unused* permissions in a live environment.', 57, 'm_57_1', 4, NULL, NULL),
  ('mock_54_all_1775003381569', 'A third-party auditing firm requires temporary, programmatic access to specific Amazon S3 buckets in a client''s AWS account. The client wants to grant this access securely, ensuring that only the specific auditing firm can assume the role and prevent confused deputy attacks. The solution should avoid creating long-term credentials.', '["Create an IAM role in the client''s account with a trust policy that specifies the auditing firm''s AWS account ID and an `ExternalId` condition key.","Generate an IAM user with programmatic access keys for the auditing firm and provide them with the credentials directly.","Configure a resource-based policy on each Amazon S3 bucket to allow access from the auditing firm''s AWS account ID.","Set up an AWS Site-to-Site VPN connection between the client''s VPC and the auditing firm''s network, then grant access via security groups."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the secure and recommended method for granting cross-account access to a third party. By creating an IAM role with a trust policy that includes the auditing firm''s AWS account ID and an `sts:ExternalId` condition key, the client ensures that only the specific firm, when providing the correct `ExternalId`, can assume the role. This prevents confused deputy attacks and provides temporary credentials via AWS STS. Option B (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users with long-term credentials, which is not recommended for third-party access due to the security risks associated with long-lived keys and manual rotation. Option C (incorrect) would grant access to the entire auditing firm''s account, making it difficult to restrict access to specific IAM principals within that account and does not provide the `ExternalId` protection against confused deputy attacks, representing anti-pattern [ap-4.2-001]. Option D (incorrect) is a network connectivity solution, not an identity and access management solution, and does not address the requirement for secure programmatic access or the prevention of confused deputy attacks.', 57, 'm_57_1', 5, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company is migrating its on-premises applications to AWS. Their employees currently authenticate against an on-premises Active Directory. They need to provide these employees with seamless access to the AWS Management Console and CLI across multiple AWS accounts without managing separate credentials in AWS.', '["Create individual IAM users in each AWS account for every employee and synchronize passwords with Active Directory.","Deploy AWS IAM Identity Center and integrate it with the on-premises Active Directory using AWS Directory Service.","Set up a custom SAML 2.0 identity provider on an Amazon EC2 instance to federate Active Directory with AWS.","Use Amazon Cognito User Pools to manage employee identities and configure it to use Active Directory as an external identity provider."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient and secure way to achieve seamless access for employees authenticating against an on-premises Active Directory. AWS IAM Identity Center (successor to AWS SSO) is designed for this exact purpose, providing centralized access management to multiple AWS accounts and integrating directly with Active Directory via AWS Directory Service. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users for human access, which is highly unscalable, increases administrative overhead, and requires managing long-term credentials. Option C (incorrect) would require significant development and maintenance effort for a custom federation solution, which is unnecessary given AWS IAM Identity Center''s capabilities. Option D (incorrect) is primarily for customer-facing applications and external users, not for internal workforce access, making it an unsuitable choice for this scenario.', 57, 'm_57_1', 6, NULL, NULL),
  ('mock_54_all_1775003381569', 'A financial institution needs to ensure that all human users accessing their AWS environment are authenticated through a centralized identity provider and are not using long-term AWS IAM user credentials. They want to enforce this across all accounts in their AWS Organization as a preventive control.', '["Create an IAM user for each employee and enforce MFA, then manually audit for non-compliant users.","Implement a custom script to periodically delete all IAM users that are not associated with a specific group.","Configure IAM permission boundaries on all IAM roles to restrict access to only temporary credentials.","Deploy AWS IAM Identity Center and use an AWS Organizations Service Control Policy (SCP) to deny `iam:CreateUser` and `iam:CreateAccessKey`."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the most robust and preventive solution. AWS IAM Identity Center centralizes human user authentication, issuing temporary credentials. An AWS Organizations Service Control Policy (SCP) denying `iam:CreateUser` and `iam:CreateAccessKey` across all accounts effectively prevents the creation of long-term IAM user credentials, enforcing the use of IAM Identity Center for human access. Option A (incorrect) represents anti-pattern [ap-4.1-002] by relying on IAM users and manual auditing, which is reactive, not preventive, and prone to human error. Option B (incorrect) is a destructive and reactive approach that could disrupt legitimate workloads and is not a preventive control. Option C (incorrect) is not directly effective for preventing the creation of IAM users or long-term credentials; permission boundaries restrict the maximum permissions an IAM principal can have, not how they authenticate.', 57, 'm_57_1', 7, NULL, NULL),
  ('mock_54_all_1775003381569', 'An AWS account administrator wants to review all existing IAM policies to identify any that grant unintended access to external AWS accounts or entities outside their AWS Organization. They need a tool to quickly pinpoint these potential security risks and ensure compliance with security best practices.', '["Use AWS IAM Access Analyzer to identify resources shared with external entities.","Manually inspect every IAM policy and resource-based policy across all accounts.","Configure AWS Config rules to detect policies with `*` in the `Principal` element.","Enable AWS CloudTrail logging and analyze logs for cross-account access events."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient and effective solution. AWS IAM Access Analyzer helps identify resources in your AWS accounts that are shared with an external entity. It analyzes resource-based policies (like S3 bucket policies, SQS queue policies, IAM roles trust policies) to identify potential unintended access, making it ideal for pinpointing external access risks. Option B (incorrect) is a manual, time-consuming, and error-prone process that is not scalable for large environments. Option C (incorrect) can help identify broad permissions but doesn''t specifically focus on *external* access and might miss more subtle external grants. Option D (incorrect) is useful for auditing *actual* access events but does not proactively identify *potential* external access granted by policies before it occurs.', 57, 'm_57_1', 8, NULL, NULL),
  ('mock_54_all_1775003381569', 'A mobile gaming company needs to allow guest users to access certain public game data stored in Amazon S3 without requiring them to sign up or log in. These guest users should have temporary, unauthenticated access with minimal configuration overhead.', '["Create an IAM user for each guest user with read-only access to the S3 bucket.","Configure Amazon Cognito Identity Pools to support unauthenticated identities and grant them temporary read-only access to the S3 bucket.","Make the Amazon S3 bucket publicly readable by attaching a public bucket policy.","Implement a custom web application on Amazon EC2 that serves the S3 data to guest users."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the recommended approach for providing temporary, unauthenticated access to guest users. Amazon Cognito Identity Pools (federated identities) can be configured to support unauthenticated identities, which can then be granted temporary, limited-privilege AWS credentials via AWS STS. This allows guest users to directly access services like Amazon S3 with defined permissions. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users, which is not suitable for guest access due to the overhead of managing individual users and long-term credentials. Option C (incorrect) is a security anti-pattern, making the entire S3 bucket publicly readable, which can expose sensitive data and is not granular enough for temporary, limited access. Option D (incorrect) introduces unnecessary operational overhead for managing an EC2 instance and a custom application when Amazon Cognito Identity Pools can handle this functionality natively.', 57, 'm_57_1', 9, NULL, NULL);

