INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A company wants to enforce a strict security policy across all accounts in its AWS Organization, preventing any IAM principal from launching Amazon EC2 instances of a specific type (e.g., `t2.micro`) for cost control and security reasons. This policy must be a preventive control that applies universally.', '["Apply an IAM permission boundary to all IAM roles, denying the launch of `t2.micro` instances.","Configure AWS Config rules to detect and remediate the launch of `t2.micro` instances.","Implement an AWS Organizations Service Control Policy (SCP) that explicitly denies `ec2:RunInstances` with a condition for `t2.micro` instance types.","Create an AWS Lambda function triggered by AWS CloudTrail events to terminate any `t2.micro` instances launched."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective preventive control for enforcing this policy across an entire AWS Organization. An AWS Organizations Service Control Policy (SCP) can explicitly deny the `ec2:RunInstances` action when the `ec2:InstanceType` condition key matches `t2.micro`. SCPs apply to all accounts within the Organizational Unit (OU) or Organization, including the root user, making them a powerful preventive guardrail. Option A (incorrect) would require applying and managing permission boundaries on every single IAM role, which is administratively complex and might not cover all possible principals. Option B (incorrect) is a detective and reactive control; it detects non-compliance after the fact, rather than preventing it. Option D (incorrect) is also a reactive control; it allows the instance to be launched before terminating it, which does not meet the requirement for a preventive control.', 57, 'm_57_2', 10, NULL, NULL),
  ('mock_54_all_1775003381569', 'A large enterprise wants to implement Attribute-Based Access Control (ABAC) for their Amazon EC2 instances. They want to ensure that developers can only manage EC2 instances that are tagged with their specific project ID, regardless of the instance type or region. This approach should minimize the number of IAM policies required.', '["Create an IAM policy that uses IAM condition keys to match the `aws:ResourceTag/Project` tag with the `aws:PrincipalTag/Project` tag.","Create separate IAM policies for each project ID, explicitly listing the EC2 instance ARNs for that project.","Implement an AWS Organizations Service Control Policy (SCP) to restrict EC2 actions based on instance tags.","Use Amazon EC2 security groups to control access to instances based on their project ID."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the core mechanism for implementing Attribute-Based Access Control (ABAC) in AWS. By using IAM condition keys like `aws:ResourceTag/Project` and `aws:PrincipalTag/Project` (or `aws:RequestTag/Project` for actions that create resources), a single IAM policy can dynamically grant access based on matching tags between the requesting principal and the target resource. This significantly reduces the number of policies needed compared to traditional role-based access control. Option B (incorrect) would lead to an unmanageable number of IAM policies as the number of projects and instances grows, violating the goal of minimizing policies. Option C (incorrect) is a preventive control at the organizational level but is typically used for broader guardrails, not granular, dynamic ABAC for specific resource management. While SCPs can use tags, the primary mechanism for ABAC for principals is within IAM identity policies. Option D (incorrect) controls network traffic, not management actions on EC2 instances, and is unrelated to ABAC for resource management.', 57, 'm_57_2', 11, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team needs to delegate administrative permissions for Amazon GuardDuty to a specific security operations team in a separate AWS account. They want to use a cross-account role to grant this access, ensuring that the delegated team can only manage GuardDuty resources and nothing else.', '["Create an IAM user in the GuardDuty account for the security operations team.","Create an IAM role in the GuardDuty account with a trust policy allowing the security operations account to assume it, and attach a policy with `GuardDuty:*` permissions.","Attach a resource-based policy to GuardDuty detectors to allow access from the security operations account.","Configure AWS Organizations Service Control Policies (SCPs) to grant GuardDuty permissions to the security operations account."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the standard and most secure pattern for delegating cross-account access. By creating an IAM role in the GuardDuty account (the resource account) with a trust policy that specifies the security operations account ID (the trusting account), and then attaching a granular policy (e.g., `GuardDuty:*`) to that role, you enable the security operations team to assume this role and manage only GuardDuty resources. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users for human access, which is not suitable for cross-account delegation and involves managing long-term credentials. Option C (incorrect) is not applicable; GuardDuty detectors do not support resource-based policies for cross-account access in this manner. Option D (incorrect) is used for preventive guardrails across an Organization, not for granting specific cross-account access to a particular service; SCPs cannot grant permissions, only restrict them.', 57, 'm_57_2', 12, NULL, NULL),
  ('mock_54_all_1775003381569', 'A data lake team in Account A needs to access an AWS Glue Data Catalog in Account B to run ETL jobs. The security team wants to grant this access using the principle of least privilege, allowing Account A''s Glue service role to read metadata from Account B''s Data Catalog.', '["Create an IAM user in Account B for the data lake team and provide them with credentials.","Modify Account A''s Glue service role to include permissions to access Account B''s Glue Data Catalog.","Create an IAM role in Account B that trusts Account A''s AWS account ID and attach a policy with `glue:Get*` permissions.","Attach a resource-based policy to the AWS Glue Data Catalog in Account B that grants `glue:Get*` permissions to Account A''s Glue service role ARN."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most direct and secure method for granting cross-account access to an AWS Glue Data Catalog. By attaching a resource-based policy directly to the Glue Data Catalog in Account B, you can explicitly grant `glue:Get*` permissions to the specific AWS Glue service role ARN from Account A. This approach adheres to the principle of least privilege and keeps the access policy with the resource. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users, which is not suitable for programmatic service-to-service access. Option B (incorrect) is not possible; a service role in Account A cannot directly grant itself permissions to resources in Account B; the resource owner (Account B) must grant the permission. Option C (incorrect) describes a cross-account role assumption pattern, which is also valid, but the question specifically asks for the Glue Data Catalog policy to explicitly permit access, making a resource-based policy on the Data Catalog the more direct answer in this context.', 57, 'm_57_2', 13, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company has multiple development teams, each responsible for different applications. They want to restrict access to Amazon DynamoDB tables such that a team can only access tables tagged with their team name. This must be dynamically enforced without creating separate IAM policies for each table or team.', '["Implement an IAM policy that uses IAM condition keys to match the `dynamodb:ResourceTag/Team` tag with the `aws:PrincipalTag/Team` tag.","Create separate IAM policies for each DynamoDB table, explicitly listing the allowed IAM roles for that table.","Use AWS Organizations Service Control Policies (SCPs) to restrict DynamoDB actions based on table tags.","Configure Amazon DynamoDB stream processing to filter access based on team names."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution for implementing Attribute-Based Access Control (ABAC) for Amazon DynamoDB tables. By using IAM condition keys like `dynamodb:ResourceTag/Team` and `aws:PrincipalTag/Team` in an IAM policy, access can be dynamically granted based on matching tags between the requesting principal (e.g., a role assumed by a team member) and the target DynamoDB table. This approach centralizes policy management and avoids creating numerous individual policies. Option B (incorrect) would lead to a proliferation of IAM policies, increasing administrative overhead and complexity, contradicting the goal of dynamic enforcement without separate policies. Option C (incorrect) is used for broader preventive guardrails at the organizational level and cannot dynamically grant granular access based on principal tags. Option D (incorrect) is for capturing changes to DynamoDB tables and is unrelated to controlling access to the tables themselves.', 57, 'm_57_2', 14, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security administrator needs to ensure that all new IAM roles created within their AWS Organization cannot grant permissions beyond a predefined set of security guardrails. This should apply to all roles, regardless of the identity-based policies attached to them, to enforce least privilege.', '["Implement an AWS Organizations Service Control Policy (SCP) to restrict the `iam:AttachRolePolicy` action.","Apply an IAM permission boundary to all new IAM roles, defining the maximum permissions they can possess.","Use AWS Config rules to detect and flag IAM roles that have overly permissive policies.","Configure AWS IAM Access Analyzer to identify roles with external access and then manually remediate."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective way to enforce security guardrails for IAM roles. An IAM permission boundary is an advanced feature for setting the maximum permissions that an identity-based policy can grant to an IAM entity (user or role). When a permission boundary is attached to a role, the effective permissions are the intersection of the identity-based policy and the permissions boundary, ensuring that the role cannot exceed the defined guardrails. Option A (incorrect) would prevent attaching policies but doesn''t define the maximum permissions a role can have. Option C (incorrect) is a detective control, identifying issues after they occur, rather than preventing them. Option D (incorrect) focuses on external access and is a detective control, not a preventive mechanism for limiting the maximum permissions of internal roles.', 57, 'm_57_2', 15, NULL, NULL),
  ('mock_54_all_1775003381569', 'A compliance requirement dictates that no IAM principal in any AWS account within an AWS Organization should be able to disable AWS CloudTrail logging. This must be a preventive control that applies to all accounts, including the management account.', '["Configure an IAM permission boundary for all IAM roles, denying `cloudtrail:StopLogging`.","Use AWS Config rules to detect and remediate instances where CloudTrail logging is disabled.","Implement an AWS Organizations Service Control Policy (SCP) that explicitly denies `cloudtrail:StopLogging` and `cloudtrail:DeleteTrail`.","Create an AWS Lambda function triggered by AWS CloudTrail events to re-enable logging if it''s stopped."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most robust preventive control for this requirement. An AWS Organizations Service Control Policy (SCP) can explicitly deny `cloudtrail:StopLogging` and `cloudtrail:DeleteTrail` across all accounts in the Organization. SCPs apply to all principals, including the root user, ensuring that CloudTrail logging cannot be disabled or trails deleted, thus meeting the preventive control requirement. Option A (incorrect) would require applying and managing permission boundaries on every single IAM role, which is administratively complex and does not apply to the root user. Option B (incorrect) is a detective and reactive control; it detects non-compliance after the fact, rather than preventing it. Option D (incorrect) is also a reactive control; it allows the logging to be stopped before attempting to re-enable it, which does not meet the requirement for a preventive control.', 57, 'm_57_2', 16, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team wants to grant an external vendor temporary access to perform specific read-only operations on Amazon S3 buckets in their AWS account. They need to ensure that the vendor can only assume the role if they provide a unique identifier, preventing unauthorized third parties from assuming the role.', '["Create an IAM user for the external vendor with programmatic access keys and attach a read-only S3 policy.","Configure a resource-based policy on each Amazon S3 bucket to allow access from the vendor''s AWS account ID.","Set up an AWS Site-to-Site VPN connection to the vendor''s network and use network ACLs to restrict access.","Create an IAM role with a trust policy that specifies the vendor''s AWS account ID and includes an `sts:ExternalId` condition key."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the secure and recommended method for granting cross-account access to an external third party. By creating an IAM role with a trust policy that includes the vendor''s AWS account ID and an `sts:ExternalId` condition key, the client ensures that only the specific vendor, when providing the correct `ExternalId`, can assume the role. This prevents confused deputy attacks (anti-pattern [ap-4.2-001]) and provides temporary credentials via AWS STS. Option A (incorrect) represents anti-pattern [ap-4.1-002] by creating IAM users with long-term credentials, which is not recommended for third-party access due to the security risks associated with long-lived keys and manual rotation. Option B (incorrect) would grant access to the entire vendor''s account, making it difficult to restrict access to specific IAM principals within that account and does not provide the `ExternalId` protection against confused deputy attacks, representing anti-pattern [ap-4.2-001]. Option C (incorrect) is a network connectivity solution, not an identity and access management solution, and does not address the requirement for secure programmatic access or the prevention of confused deputy attacks.', 57, 'm_57_2', 17, NULL, NULL);

