INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A large enterprise is expanding its AWS footprint, requiring new AWS accounts for various development teams. The security team needs to establish a standardized, secure baseline for these accounts and ensure central governance from day one. Which approach provides the LEAST operational overhead for initial setup and ongoing management?', '["Implement AWS Control Tower to provision new accounts with predefined guardrails and a landing zone.","Manually configure AWS Organizations, create OUs, and apply Service Control Policies (SCPs) to each account.","Use AWS CloudFormation StackSets to deploy a baseline of security resources and configurations to new accounts.","Develop custom scripts with AWS Lambda and AWS Step Functions to automate account creation and security hardening."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes AWS Control Tower, which automates the setup of a secure, multi-account AWS environment with a landing zone, predefined guardrails, and account vending capabilities. This significantly reduces operational overhead for initial setup and ongoing governance. Option B (incorrect) involves manual configuration of AWS Organizations, which provides the framework but requires more effort to establish the full secure baseline and governance compared to Control Tower. Option C (incorrect) uses AWS CloudFormation StackSets, which is excellent for deploying resources consistently across accounts but doesn''t provide the full landing zone, account vending, or built-in guardrails that Control Tower offers, thus requiring more manual integration. Option D (incorrect) involves developing custom scripts, which would incur significant development and maintenance overhead, directly contradicting the ''LEAST operational overhead'' constraint.', 59, 'm_59_1', 1, NULL, NULL),
  ('mock_54_all_1775003381569', 'In a multi-account AWS environment managed by AWS Organizations, the security team needs to prevent developers in a specific Organizational Unit (OU) from creating Amazon S3 buckets that allow public access. Which solution implements a PREVENTIVE control that applies consistently across all accounts within that OU?', '["Configure an AWS Config rule to detect publicly accessible Amazon S3 buckets and trigger remediation.","Apply a Service Control Policy (SCP) in AWS Organizations to the OU, denying `s3:PutBucketAcl` actions for public access.","Set up Amazon Security Hub to aggregate findings related to publicly accessible Amazon S3 buckets.","Implement IAM permission boundaries on all developer roles within the OU to restrict S3 bucket policies."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) involves applying a Service Control Policy (SCP) in AWS Organizations. SCPs are preventive controls that define the maximum available permissions for accounts within an OU, effectively denying actions like `s3:PutBucketAcl` for public access before they can occur. Option A (incorrect) uses an AWS Config rule, which is a detective control; it identifies non-compliant resources *after* they are created, not preventing their creation. Option C (incorrect) uses Amazon Security Hub, which aggregates security findings from various services but does not prevent actions from happening. Option D (incorrect) suggests IAM permission boundaries, which are applied to individual IAM roles and users, making them less scalable and consistent for a broad OU-level prevention compared to an SCP.', 59, 'm_59_1', 2, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security operations center (SOC) needs a unified and actionable view of security findings generated by various AWS security services across 50 AWS accounts and multiple AWS Regions. The goal is to centralize monitoring with MINIMAL custom integration effort. Which service should they use?', '["Manually review AWS Config compliance reports from each account and Region.","Develop custom AWS Lambda functions to pull findings from each service and centralize them.","Configure Amazon Security Hub for cross-account and cross-Region aggregation of security findings.","Utilize AWS Audit Manager to collect evidence of security findings for centralized review."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon Security Hub, which is designed to provide a comprehensive view of security alerts and security posture across an AWS environment. It automatically aggregates findings from various AWS security services (like AWS Config, Amazon GuardDuty, AWS IAM Access Analyzer) and supports cross-account and cross-Region aggregation, requiring minimal custom integration. Option A (incorrect) involves manual review, which is not scalable or efficient for 50 accounts and multiple Regions. Option B (incorrect) requires significant custom development and maintenance, contradicting the ''MINIMAL custom integration effort'' constraint. Option D (incorrect) uses AWS Audit Manager, which is primarily for automating evidence collection for audits, not for real-time, actionable security findings aggregation and monitoring.', 59, 'm_59_1', 3, NULL, NULL),
  ('mock_54_all_1775003381569', 'A rapidly growing company needs to ensure that all new AWS accounts provisioned for project teams automatically conform to a baseline of security best practices, including specific encryption and logging configurations, from day one. Which solution BEST automates compliance checks and enforcement for these new accounts?', '["Implement AWS Organizations SCPs to prevent non-compliant resource creation.","Manually deploy AWS Config rules to each new account after it is provisioned.","Use AWS Service Catalog to provide pre-approved, compliant infrastructure templates.","Deploy AWS Config conformance packs through AWS Control Tower or AWS Organizations."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) involves deploying AWS Config conformance packs, ideally through AWS Control Tower or AWS Organizations. Conformance packs are collections of AWS Config rules and remediation actions that allow you to package and deploy a common set of compliance checks and best practices across multiple accounts, automating the enforcement and monitoring of security baselines from the moment an account is provisioned. Option A (incorrect) uses SCPs, which are preventive but operate at a broader permission level and don''t provide the detailed resource-level compliance checks and reporting that Config conformance packs offer. Option B (incorrect) requires manual deployment of Config rules, which is not automated or scalable for ''all new accounts.'' Option C (incorrect) uses AWS Service Catalog to provide templates, which helps ensure compliant provisioning, but conformance packs provide continuous monitoring and reporting against a baseline for *all* resources, not just those provisioned through Service Catalog.', 59, 'm_59_1', 4, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company with a multi-account strategy needs to streamline the process of provisioning new AWS accounts for its various business units. Each new account must adhere to a predefined security baseline, including specific network configurations and mandatory guardrails. Which approach offers the most automated and governed account vending solution?', '["Utilize AWS Control Tower''s Account Factory to create new accounts with pre-configured security and network settings.","Manually create new accounts in AWS Organizations and then apply CloudFormation templates for baseline configurations.","Develop a custom Python script that uses the AWS SDK to create accounts and configure initial security settings.","Provide AWS Service Catalog portfolios to business units for self-service provisioning of resources within existing accounts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) describes AWS Control Tower''s Account Factory, which is specifically designed for automated, governed account vending. It provisions new AWS accounts that are pre-configured with a secure baseline, network settings, and guardrails, significantly reducing manual effort and ensuring consistency. Option B (incorrect) involves manual steps and then applying CloudFormation, which is less automated and more prone to errors than Control Tower''s integrated solution. Option C (incorrect) would incur significant development and maintenance overhead for custom scripting, which is less efficient than a managed service like Control Tower. Option D (incorrect) focuses on provisioning resources *within* existing accounts, not provisioning new accounts themselves, making it unsuitable for the requirement.', 59, 'm_59_1', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'An organization needs to continuously monitor its AWS resources for compliance against internal security policies, such as ensuring all Amazon S3 buckets are encrypted with AWS Key Management Service (AWS KMS) keys and do not allow public access. Which service provides the MOST automated and continuous compliance monitoring and reporting?', '["Manually review Amazon S3 bucket policies and encryption settings on a weekly basis.","Implement AWS Config rules to evaluate resource configurations against desired compliance standards.","Use AWS Audit Manager to collect evidence of compliance for periodic internal audits.","Configure Amazon Security Hub to aggregate security findings from various services for review."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS Config rules, which provide continuous, automated monitoring of AWS resource configurations against desired compliance standards. AWS Config can detect non-compliant S3 buckets (e.g., unencrypted or publicly accessible) and report on their status, offering the most automated and continuous solution for this requirement. Option A (incorrect) involves manual review, which is not automated or scalable. Option C (incorrect) uses AWS Audit Manager, which is designed for automating evidence collection for audits, not for continuous, real-time compliance monitoring and reporting. Option D (incorrect) uses Amazon Security Hub to aggregate findings, but AWS Config is the service that actually *evaluates* the resource configurations against the rules.', 59, 'm_59_3', 6, NULL, NULL),
  ('mock_54_all_1775003381569', 'A compliance officer needs to regularly generate reports demonstrating adherence to industry standards like PCI DSS and HIPAA. This requires collecting evidence from various AWS services, including AWS CloudTrail logs, AWS Config compliance history, and IAM access reports. Which AWS service is designed to streamline this evidence collection process for audits?', '["Configure AWS Config conformance packs to define compliance baselines.","Aggregate security findings from various services using Amazon Security Hub.","Utilize AWS Audit Manager to automate the collection of audit evidence.","Manually download and consolidate reports from individual AWS services."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes AWS Audit Manager, which automates the collection of evidence from various AWS services to help prepare for audits. It maps AWS resource data to controls for common compliance frameworks, significantly streamlining the audit preparation process. Option A (incorrect) uses AWS Config conformance packs to define and check compliance baselines, but not specifically to *collect evidence* for an audit report. Option B (incorrect) uses Amazon Security Hub to aggregate security findings, which is useful for security posture but not for structured audit evidence collection across compliance frameworks. Option D (incorrect) involves manual collection, which is inefficient and prone to errors, failing the ''streamline'' constraint.', 59, 'm_59_3', 7, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team needs a centralized dashboard to view and manage security findings from multiple AWS services, including AWS Config, Amazon GuardDuty, and AWS IAM Access Analyzer, across several AWS accounts. The primary goal is to have a consolidated, standardized view of the security posture. Which AWS service should be implemented?', '["AWS Organizations to manage security policies across accounts.","AWS CloudFormation StackSets to deploy security monitoring resources.","AWS Config to evaluate resource compliance against security rules.","Amazon Security Hub to aggregate and normalize security findings."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Security Hub, which is specifically designed to aggregate, organize, and prioritize security findings from various AWS services (like AWS Config, Amazon GuardDuty, AWS IAM Access Analyzer) and partner solutions. It provides a centralized, standardized view of security posture across multiple accounts and Regions. Option A (incorrect) uses AWS Organizations for account management and policy enforcement, not for aggregating security findings. Option B (incorrect) uses AWS CloudFormation StackSets for deploying resources, not for monitoring and aggregating security findings. Option C (incorrect) uses AWS Config to evaluate resource compliance, but it doesn''t aggregate findings from *other* security services into a single dashboard.', 59, 'm_59_3', 8, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company needs to ensure that all newly deployed Amazon EC2 instances automatically comply with a specific security group configuration, such as disallowing inbound SSH from 0.0.0.0/0. If a non-compliant instance is launched, it should be flagged immediately. Which solution provides automated detection and reporting of such non-compliance?', '["Implement AWS Config rules to continuously monitor and flag non-compliant security group configurations.","Use AWS Service Catalog to only allow provisioning of EC2 instances with compliant security groups.","Rely on AWS Audit Manager to collect evidence of security group configurations for periodic review.","Manually review security group settings for all new EC2 instances after deployment."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) involves implementing AWS Config rules. AWS Config continuously monitors resource configurations, including security groups, and can automatically flag any instance that deviates from the desired compliant state (e.g., allowing SSH from 0.0.0.0/0). This provides automated detection and reporting. Option B (incorrect) uses AWS Service Catalog, which is a preventive control for provisioning, ensuring new resources *start* compliant, but it doesn''t continuously monitor for changes *after* provisioning or for resources deployed outside Service Catalog. Option C (incorrect) uses AWS Audit Manager for evidence collection, not for continuous, real-time detection and flagging of non-compliance. Option D (incorrect) is a manual process, which is not automated and fails the requirement for immediate flagging.', 59, 'm_59_3', 9, NULL, NULL),
  ('mock_54_all_1775003381569', 'A financial institution must maintain a continuous record of compliance status for its AWS resources against a custom set of security benchmarks and be able to quickly identify deviations. The solution must also provide a centralized view of compliance posture across multiple accounts. Which approach is MOST effective?', '["Manually review AWS CloudFormation templates and resource configurations for compliance.","Deploy custom AWS Config rules and aggregate their findings in Amazon Security Hub.","Use AWS Audit Manager for continuous monitoring and deviation detection.","Implement AWS Organizations Service Control Policies (SCPs) for all compliance checks."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach. Custom AWS Config rules allow the institution to define specific security benchmarks and continuously evaluate resource configurations against them, providing a continuous record of compliance and quick deviation identification. Aggregating these findings in Amazon Security Hub provides a centralized view across multiple accounts. Option A (incorrect) involves manual review, which is not continuous, automated, or scalable. Option C (incorrect) misrepresents AWS Audit Manager''s primary function; Audit Manager is for automating evidence collection for audits, not for continuous monitoring and real-time deviation detection. Option D (incorrect) uses SCPs, which are preventive controls to restrict actions, but they do not provide continuous, detailed compliance checks or a compliance status record against custom benchmarks for existing resources.', 59, 'm_59_3', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A security engineer needs to identify potential security misconfigurations in existing AWS resources across several accounts, such as unencrypted Amazon EBS volumes or publicly accessible Amazon RDS instances. The primary goal is to proactively discover security vulnerabilities and non-compliance. Which approach is MOST effective for this purpose?', '["Manually review AWS CloudFormation templates for all deployed stacks.","Utilize AWS Service Catalog to review the security posture of provisioned resources.","Deploy AWS Config rules across accounts to continuously detect non-compliant resources.","Rely on AWS Audit Manager to identify real-time security gaps in existing infrastructure."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) involves deploying AWS Config rules across accounts. AWS Config continuously evaluates the configuration of AWS resources against desired rules, making it highly effective for proactively detecting security misconfigurations like unencrypted EBS volumes or publicly accessible RDS instances in existing infrastructure. Option A (incorrect) involves manual review of CloudFormation templates, which is static and does not reflect the current state of deployed resources or changes made outside of CloudFormation. Option B (incorrect) uses AWS Service Catalog, which is for provisioning and governing *new* resources, not for auditing the security posture of *existing* resources. Option D (incorrect) misrepresents AWS Audit Manager; it automates evidence collection for audits, but it does not provide real-time, proactive detection of security gaps in the way AWS Config does.', 59, 'm_59_4', 11, NULL, NULL),
  ('mock_54_all_1775003381569', 'The CISO requires a weekly summary of the organization''s overall security posture, including high-severity findings from various AWS security services, to identify critical security gaps and inform strategic decisions. Which solution provides the MOST centralized and aggregated security insights for executive reporting?', '["Generate individual compliance reports from AWS Config conformance packs.","Configure Amazon Security Hub to aggregate findings from all linked accounts and services.","Manually collect logs from AWS CloudTrail and analyze them for security events.","Use AWS Organizations to manage account security policies and review their effectiveness."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Security Hub. It is designed to aggregate, normalize, and prioritize security findings from various AWS security services (like AWS Config, Amazon GuardDuty, AWS IAM Access Analyzer) and partner solutions across multiple accounts. This provides a centralized, high-level view of the overall security posture, ideal for executive reporting and identifying critical security gaps. Option A (incorrect) generates detailed compliance reports from AWS Config, which are valuable but less aggregated and actionable for a high-level security posture summary. Option C (incorrect) involves manual log collection and analysis, which is labor-intensive and not suitable for a ''MOST centralized and aggregated'' solution. Option D (incorrect) uses AWS Organizations for governance, not for aggregating security findings or providing a security posture summary.', 59, 'm_59_4', 12, NULL, NULL),
  ('mock_54_all_1775003381569', 'A development team frequently deploys AWS resources without proper tagging, leading to challenges in identifying resource ownership, cost allocation, and applying security policies consistently. The security team needs to identify existing resources lacking mandatory security tags to address these governance gaps. Which approach is MOST effective?', '["Review AWS CloudFormation StackSets for tagging compliance during deployment.","Utilize AWS Service Catalog to enforce tagging during resource provisioning.","Implement AWS Config rules to check for mandatory tags on resources and report non-compliance.","Rely on AWS Audit Manager to flag untagged resources during an audit cycle."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) involves implementing AWS Config rules to check for mandatory tags on resources. AWS Config can continuously monitor existing resources, identify those missing required tags, and report on their non-compliance, directly addressing the need to identify existing gaps. Option A (incorrect) focuses on CloudFormation StackSets, which is for deploying resources, not for auditing existing resources for tagging compliance. Option B (incorrect) uses AWS Service Catalog, which is excellent for enforcing tagging on *new* resources provisioned through it, but it does not identify gaps in *existing* resources deployed outside Service Catalog. Option D (incorrect) uses AWS Audit Manager, which collects evidence for audits, but AWS Config is more suited for continuous, proactive detection and reporting of tagging non-compliance.', 59, 'm_59_4', 13, NULL, NULL),
  ('mock_54_all_1775003381569', 'An organization needs to ensure that all AWS accounts consistently enforce a baseline of security controls, and any deviation from this baseline should be immediately flagged as a security gap. This requires a standardized approach for defining and checking compliance across the entire AWS Organization. Which solution is MOST appropriate?', '["Manually audit AWS Service Catalog portfolios for security compliance.","Deploy AWS Config conformance packs across all accounts via AWS Organizations.","Use AWS Control Tower for continuous monitoring of security gaps.","Rely on Amazon Security Hub for defining security baselines and detecting deviations."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate solution. AWS Config conformance packs allow you to define a standardized set of AWS Config rules and deploy them across all accounts in an AWS Organization. This ensures consistent enforcement of a security baseline and immediately flags any deviations as non-compliant resources, effectively identifying security gaps. Option A (incorrect) involves manual auditing of Service Catalog, which is not automated, continuous, or comprehensive for all resources. Option C (incorrect) states using AWS Control Tower for continuous monitoring of security gaps; while Control Tower establishes guardrails, AWS Config conformance packs are the specific mechanism for detailed, continuous compliance checks. Option D (incorrect) misrepresents Amazon Security Hub; Security Hub aggregates and normalizes findings, but AWS Config is the service used for defining and checking security baselines.', 59, 'm_59_4', 14, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security auditor needs to verify that critical security controls, such as multi-factor authentication (MFA) for root users and strong password policies, are consistently applied across all organizational units (OUs) within an AWS Organization. Which combination of services provides the MOST effective way to identify accounts or OUs that deviate from these fundamental security best practices?', '["Implement AWS Organizations SCPs to detect non-compliant settings.","Review AWS CloudFormation StackSets for MFA configurations and password policies.","Utilize AWS Config rules and aggregate findings in Amazon Security Hub for a centralized view.","Use AWS Service Catalog to ensure MFA is enabled during resource provisioning."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective combination. AWS Config rules can be deployed to check for specific configurations like MFA for root users or password policy strength across accounts. Aggregating these findings in Amazon Security Hub provides a centralized, actionable view of non-compliance across OUs, allowing the auditor to quickly identify deviations. Option A (incorrect) uses SCPs, which are preventive controls to restrict actions, but they don''t *detect* existing non-compliant settings or provide detailed reporting on them. Option B (incorrect) involves CloudFormation StackSets, which are for deploying resources, not for auditing account-level security settings like MFA for root users. Option D (incorrect) uses AWS Service Catalog for resource provisioning, which is unrelated to checking account-level security controls.', 59, 'm_59_4', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_59_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_54_all_1775003381569', 'A large enterprise needs to standardize the deployment of approved AWS resources, such as specific Amazon EC2 instance types or Amazon S3 buckets with mandatory encryption, for its various development teams. The objective is to enable self-service provisioning while ensuring compliance with predefined security policies. Which AWS service should be used?', '["AWS CloudFormation StackSets for deploying resources across multiple accounts.","AWS Organizations Service Control Policies (SCPs) to restrict non-compliant resource creation.","AWS Control Tower for setting up a secure multi-account landing zone.","AWS Service Catalog to provide a curated portfolio of approved and compliant resources."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Service Catalog. It enables organizations to create and manage catalogs of IT services that are approved for use on AWS. This allows development teams to self-service provision pre-approved, compliant AWS resources (like EC2 instances or S3 buckets with specific configurations) while ensuring adherence to security policies. Option A (incorrect) uses AWS CloudFormation StackSets for deploying resources across accounts, which is a central deployment mechanism, not a self-service provisioning portal for end-users. Option B (incorrect) uses SCPs as preventive controls, but they don''t provide a self-service catalog. Option C (incorrect) uses AWS Control Tower for setting up a multi-account environment, not for self-service provisioning of individual resources within those accounts.', 59, 'm_59_2', 16, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security team wants to ensure that a mandatory set of security-related AWS Config rules is deployed and enforced across all new and existing accounts within an AWS Organization. The goal is to achieve consistent, automated deployment of these security controls across the multi-account environment. Which solution is MOST efficient?', '["Deploy AWS Config conformance packs using AWS CloudFormation StackSets across the Organization.","Manually apply AWS Config rules to each individual account after it is created or onboarded.","Use AWS Service Catalog to allow teams to deploy pre-approved AWS Config rules to their accounts.","Rely on AWS Audit Manager to detect if accounts are missing the mandatory AWS Config rules."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient solution. Deploying AWS Config conformance packs using AWS CloudFormation StackSets allows for the automated, consistent deployment and enforcement of a predefined set of AWS Config rules across all accounts within an AWS Organization. This ensures that security controls are applied uniformly and efficiently. Option B (incorrect) involves manual application, which is not automated or scalable for a multi-account environment. Option C (incorrect) uses AWS Service Catalog, which is for end-user provisioning of resources, not for central deployment of governance tools like Config rules. Option D (incorrect) uses AWS Audit Manager, which is for evidence collection, not for deploying or enforcing security controls.', 59, 'm_59_2', 17, NULL, NULL),
  ('mock_54_all_1775003381569', 'After deploying a critical application infrastructure using AWS CloudFormation, the security team needs to detect any unauthorized changes to the deployed resources that could introduce security vulnerabilities. This detection must be automated and provide alerts. Which AWS service capability is BEST suited to identify configuration drift from the intended secure baseline?', '["Use AWS Audit Manager to review changes to CloudFormation stacks.","Enable AWS Config drift detection for CloudFormation stacks to identify unauthorized modifications.","Implement AWS Organizations Service Control Policies (SCPs) to prevent unauthorized changes.","Configure Amazon Security Hub to monitor for configuration drift findings from various services."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Config drift detection for CloudFormation stacks. AWS Config can monitor CloudFormation stacks and their resources, identifying any changes that deviate from the template''s defined configuration. This directly addresses the need to detect unauthorized changes and identify configuration drift from the intended secure baseline. Option A (incorrect) uses AWS Audit Manager, which is for evidence collection and audit preparation, not for real-time detection of configuration drift. Option C (incorrect) uses SCPs, which are preventive controls that restrict actions, but they do not detect changes that have already occurred or unauthorized changes to deployed resources. Option D (incorrect) uses Amazon Security Hub to aggregate findings, but AWS Config is the service that performs the actual drift detection.', 59, 'm_59_2', 18, NULL, NULL),
  ('mock_54_all_1775003381569', 'A company wants to provide developers with pre-approved, compliant AWS CloudFormation templates for common infrastructure patterns (e.g., secure VPC, encrypted Amazon S3 bucket) to accelerate development while maintaining security. The templates should be easily discoverable and provisionable by developers. Which solution BEST meets this requirement?', '["Share CloudFormation templates via an Amazon S3 bucket with appropriate IAM policies.","Use AWS Organizations Service Control Policies (SCPs) to enforce template usage.","Publish compliant CloudFormation templates through AWS Service Catalog portfolios.","Deploy templates using AWS CloudFormation StackSets across developer accounts."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to publish compliant CloudFormation templates through AWS Service Catalog portfolios. AWS Service Catalog allows organizations to create and manage a curated catalog of IT services, enabling developers to easily discover and provision pre-approved, compliant infrastructure templates in a self-service manner, ensuring governance and security. Option A (incorrect) involves sharing templates via Amazon S3, which lacks the governance, version control, and self-service provisioning capabilities of Service Catalog. Option B (incorrect) uses SCPs, which are preventive controls, but they don''t provide a mechanism for template distribution or self-service provisioning. Option D (incorrect) uses AWS CloudFormation StackSets for central deployment, not for providing developers with a self-service catalog of templates.', 59, 'm_59_2', 19, NULL, NULL),
  ('mock_54_all_1775003381569', 'A security architect needs to implement a control that prevents any IAM user or role from creating an Amazon S3 bucket without server-side encryption enabled, across all accounts in an AWS Organization. This control must be enforced at the highest possible level. Which solution provides the MOST effective PREVENTIVE control at the organizational level?', '["Deploy an AWS Config rule to detect unencrypted Amazon S3 buckets after creation.","Configure Amazon Security Hub to flag unencrypted Amazon S3 buckets as high-severity findings.","Use AWS Service Catalog to only offer templates for encrypted Amazon S3 buckets.","Create an AWS Organizations Service Control Policy (SCP) to deny S3 bucket creation without encryption."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is to create an AWS Organizations Service Control Policy (SCP) to deny S3 bucket creation without server-side encryption. SCPs are powerful preventive controls that apply at the organizational level, restricting the maximum permissions for all accounts within an OU or the entire organization. This ensures that no IAM user or role can perform the disallowed action. Option A (incorrect) uses an AWS Config rule, which is a detective control; it detects non-compliance *after* the bucket is created, not preventing its creation. Option B (incorrect) uses Amazon Security Hub, which aggregates findings but does not prevent actions. Option C (incorrect) uses AWS Service Catalog, which is a preventive control for resources provisioned *through* the catalog, but it does not prevent users from creating unencrypted S3 buckets directly via the AWS CLI, SDK, or console outside of Service Catalog.', 59, 'm_59_2', 20, NULL, NULL);

